window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[3] = [{"id":81,"category_id":3,"category_code":"s3","source_id":1,"title":"راهنمایی ملا","content":" روزی شخصی تفنگچه ای پیدا كرد و آنرا نزد ملا برد و از او پرسید: ملا جان بگو این چی است؟ ملا نگاهی به تفنگچه انداخت و گفت: آن چپق (چلم) فرنگی است.\r\nمردی كه تفنگچه را پیدا كرده بود خوشحال شد و آنرا به دهان خود گذارده و خواست بكشد. اما ناگهان گلوله ای رها شد و مرد بیچاره نقش زمین شد. ملا نگاهی به جسد بی جان او انداخت و گفت: عجب تمباكوی خوبی داخل این چپق بود، تا یك پك كشید نشه شد و روی زمین افتاد.\r\n"},{"id":82,"category_id":3,"category_code":"s3","source_id":2,"title":"مسابقه اسب سواری ","content":"ملانصرالدین در عرصه ی مسابقه بر اسبی بنشست و یال اسب در دست گرفت. اسب تاختن آورد و ملا از پشت آن لغزید و از ابتدای یال به انتهای دمب آن رسید ! پس آواز در داد: آهای! آهای …! این اسب تمام شد یک اسب دیگر بیاورید!!!"},{"id":83,"category_id":3,"category_code":"s3","source_id":3,"title":"خدا شدن ملا ","content":" مردی بود که در حماقت برادر بزرگ ملا بود. هر شب در زیر درختی که در حوالی شهر بود میرفت و مناجات میکرد.\r\nاز جمله مناجات او این بود که : \"خدایا خود را بمن بنما\" ملا از مناجات او مطلع گشته شبی خود را در بالای درخت پنهان کرد چون مرد به عادت همیشه لب به مناجات گشود همین آیه را ذکر نمود.\r\nملا در جواب گفت \" لن ترانی \" و لیکن هرگاه یک هزار دینار در خانه ی ملا به زن او بدهی ما را خواهی دید، مرد بتعجیل هرچه تمامتر به شهر آمد یک هزار دینار برداشته به خانه ملا آمد پول را بزن او داده برگشت بپای درخت و گفت: وفا به عهد را مسئلت دارم.\r\nپس ملا عمامه خود را باز کرد و مانند طناب یکسر آنرا بدست گرفته و یکسر دیگر آنرا پایین داده گفت: بگیر و بالا به نزد ما بیا تا تو را مورد عطوفت خود بگردانیم، مرد شاد شد چنگ در او زد، ملا از آن بالا زور زد که بالا بکشد، اما عمامه پاره شد و مرد از وسط راه بزمین افتاده سرش شکست، مرد از جا برخاسته گفت : الهی پول مرا حواله ملا کردی، دیگر مرا به زمین زدن و سر مرا شکستن چه معنی داشت؟\r\n"},{"id":84,"category_id":3,"category_code":"s3","source_id":4,"title":"نان و نمک ","content":" روزی کسی ملا را بمنزلش دعوت کرد که بیا نان و نمکی بخوریم ملا باور نکرد و گمان کرد شاید غذای دیگر درکار باشد به خانه او رفت، وقتی غذا آوردند ملا جز قدری نان و نمک چیزی ندید.\r\nگدایی بر در سرای صاحبخانه آمد چیزی بخواست  صاحبخانه او را جواب گفت سائل باز سوال نمود، آن مرد گفت اگر نروی با این چوب سر ترا خواهم شکست، ملا گفت : این مرد آنقدر در قول خود صادق است که حساب ندارد تا زود است برو و جانت را بدر بر.\r\n"},{"id":85,"category_id":3,"category_code":"s3","source_id":5,"title":"حلوا ","content":" در مجلسي صحبت از حلوا پيش آمد. ملا گفت مدتي است آروزي خوردن حلوا به دلم مانده است گفتند چرا نمي پزي؟ گفت هر وقت آرد حاضر ميشود روغن نيست روغن كه پيدا شد شكر نيست گفتند كه تا حال نشده كه هر دو حاضر شود؟ گفت چرا نه، آنوقت من حاضر نبودم."},{"id":86,"category_id":3,"category_code":"s3","source_id":6,"title":"هیچی به هیچی ","content":" در زمان قضاوت ملا دو نفر نزد او آمده دعوائي اقامه كردند مدعي اظهار داشت اين شخص مرا صدا زد و گفت اين بار را بر دوش من بگذار گفتم در مقابل به من چه خواهي داد؟ گفت هيچ، منهم زحمتي كشيده بار را بر دوش او گذاشتم حال هر چه ميگويم هيچ مرا بده نميدهد. ملا گفت خيلي خوب حق داري حالا بيا اين فرش را بلند كن. وي بلند كرد ملا گفت در زير فرش چيست؟ گفتم هيچ ملا گفت اين هيچ اجرت تو بود."},{"id":87,"category_id":3,"category_code":"s3","source_id":7,"title":"خانه دو در ","content":"روزي ملا پس از اتمام درس با اصرار چند نفر از شاگردانش را به منزل دعوت نمود و آنها را تا جلو خانه آورده گفت شما منتظر باشيد تا بروم اتاق را براي شما آماده بسازم پس وارد خانه شده از زنش پرسيد در خانه چيزي است كه مهمانان را پذيرائي كنيم؟ زن گفت نه. ملا گفت پس بروم عذر مهمانان را بكنم زن در را باز كرده به مهمانها گفت: ملا در منزل نيست مهمانها گفتند اين چه حرفيست ميزني ملا همين لحظه در حضور ما داخل خانه شد ملا از پنجره صدا كرد مگر نميدانيد اين خانه دو در دارد از در ديگر بيرون رفته است."},{"id":88,"category_id":3,"category_code":"s3","source_id":8,"title":"آب شوربا ","content":" روزي دهقاني براي ملا خرگوشي هديه آورد. ملا پذيرائي مفصلي از او نموده با كمال رضايت او را راه انداخت هفتهَ ديگر برادر دهقان نزد ملا آمده خود را معرفي كرد باز ملا او را مهمان كرد و خوب قدر داني از وي نمود يك هفته بعد چند نفر به خانه ملا آمده خود را همسايگان دهقان هديه آورنده معرفي نمودند ملا شوربا تهيه نموده آنها را به اسم شورباي خرگوش ضيافت كرد. باز هفته ديگر چند نفر به خانه او آمده خود را همسايه همسايگان دهقان معرفي نمودند ملا با كمال ادب انها را به خانه آورده موقع نان چاشت يك كاسه بزرگ آب پيشروي آنها گذاشت دهاتي ها متحيرانه به كاسه آب ديدند ملا گفت: بفرمائيد نوش جان كنيد اين آب شورباي خرگوش است."},{"id":89,"category_id":3,"category_code":"s3","source_id":9,"title":"غذاي بي زحمت ","content":"غذاي چربي براي ملا هديه آوردند گفت اگر زحمت نميبود خيلي لذيد ميشد. زنش پرسيد چه زحمتي دارد غذا را تو كه پخته نكردي ديگري آورده و تو ميخوري. ملا گفت: عجب، تو هنوز نميداني شريك داشتن در خوردني زحمت است. اگر تو نميبودي لذت نان معلوم ميشد."},{"id":90,"category_id":3,"category_code":"s3","source_id":10,"title":"نامه نويسي ملا ","content":" روزي ملا پيش عريضه نويسي رفت و گفت نامه اي براي يكي از دوستانس كه در شهري ديگر زندگي ميكرد بنويسد. نامه نويس شروع به نوشتن كرد و وقتي نامه را نوشت ملا فرياد زد: بنويس پول ندارم مقداري پول برايم بفرست. نامه نويس با عصبانيت گفت: كاكا براي چي فرياد ميكشي؟ ملا گفت: چون شخصي كه برايش نامه مينويسي گوشهايش كر است. اينجاي نامه را فرياد زدم تا تو هم با صداي بلند بنويسي و او بتواند بخواند."},{"id":91,"category_id":3,"category_code":"s3","source_id":11,"title":"كيله خوردن ملا ","content":" روزي ملا چند دانه كيله خريد و با پوست شروع به خوردن آنها كرد. مردي از كنارش ميگذشت اين منظره را ديد و از وي پرسيد براي چه پوست كيله ها را نميكند و مغزش را نميخورد. ملا لبخندي زد و گفت: خوب آدم نادان من ميدانم كه در داخل آن چيست ديگر چه لزومي دارد كه پوست كيله را بكنم و بدور بياندازم."},{"id":92,"category_id":3,"category_code":"s3","source_id":12,"title":"زمستان ","content":" به ملا گفتند: زمستان امسال خيلي سرد ميشود. شما چه تهيه ديده ايد؟ گفت: لرزيدن\r\nملا و طبيب - يكروز ملانصرالدين مريض شده بود. زنش رفت طبيبي را كه تازه از فرنگ آمده بود و اصلا زبان محلي ايشان را نميدانست به بالين وي آورد. طبيب فقط دو كلمه ماشاالله و انشاالله را ياد گرفته بود. ملا از او پرسيد: داكتر صاحب آيا مرض من سخت است؟ طبيب گفت: ماشاالله..... ماشاالله. ملا دو باره سوال كرد: داكتر جان...آيا اين مرض مرا خواهد كشت؟ داكتر جواب داد: انشاالله.....انشاالله\r\n"},{"id":93,"category_id":3,"category_code":"s3","source_id":13,"title":"دروغگو ","content":" یک روز ملانصرالدین دست بچه ای را گرفت و به دکان سلمانی برد. به سلمانی گفت: من عجله دارم، اول سر مرا بتراش ، بعد هم موهای بچه را بزن\r\nسلمانی سر او را تراشید. ملا کلاهش را بر سر گذاشت و گفت: تا موهای بچه را اصلاح کنی برمی گردم. سلمانی سر بچه را هم اصلاح کرد ولی خبری از آمدن ملا نشد. به بچه گفت: چرا پدرت نمی آید؟ بچه جواب داد: او پدرم نبود. سلمانی گفت: پس کی بود؟ بچه گفت:مردی بود که درکوچه به من گفت بیا دونفری برویم مجانی اصلاح کنیم!\r\n"},{"id":94,"category_id":3,"category_code":"s3","source_id":14,"title":"روزه ","content":" شخصی در ماه شعبان، نزد ملانصرالدین آمد تا از او زیتون نسیه بخرد. ملانصرالدین به او گفت: \"قدری از آن بخوری و ببین بی عیب باشد\". آن فرد جواب داد: \" برای قضای روزه ماه رمضان، امروز روزه ام\". ملانصرالدین خطاب به آن فرد گفت: \"برو که هرگز به تو نسیه نمی دهم. تو قرض خدا را تا به حال به تاخیر انداختی، پول زیتون بنده خدا را کی خواهی داد!!؟\""},{"id":95,"category_id":3,"category_code":"s3","source_id":15,"title":"ناهار ملا ","content":" ملا نصرالدین ناهار ماست خورد و از خانه بیرون رفت. در راه فردی از او پرسید:\"ملا نصرالدین ناهار چه خوردی؟\" . ملانصرالدین جواب داد:\"بوقلمون\". فرد سوال کننده در جواب ملانصرالدین گفت:\"لابد سفیدی روی ریشت هم، فضله ی بوقلمونی است که ناهار خورده ای!\""},{"id":96,"category_id":3,"category_code":"s3","source_id":16,"title":"جوانی ملا ","content":" روزی ملانصرالدین خواست سوار اسبی شود ولی نتوانست. گفت: افسوس از جوانی\r\nولی بعد پیش خودش گفت: خودمانیم، در جوانی هم چیزی نبودیم.\r\n"},{"id":97,"category_id":3,"category_code":"s3","source_id":17,"title":"داماد ملا ","content":" ملانصرالدین، فردی را به دامادی قبول کرد. با پخش این خبردر شهر، برخی از خواستگاران دختر ملانصرالدین که انتظار داشتند وی یکی از آنها را به دامادی خود برگزیند، نزد ملانصرالدین رفتند و گفتند: \"ملا چه کردی! این فرد دنیاطلب است و قصد دارد از طریق ازدواج با دختر تو، ثروتت را به چنگ آورد\"\r\nولی ملانصرالدین در کمال خونسردی در جواب آنها گفت: \"اگر ثروتی یافت، مختار است هرچه خواست با آن بکند\"\r\n"},{"id":98,"category_id":3,"category_code":"s3","source_id":18,"title":"آدم","content":" ملانصرالدین از شخص بسیار بدترکیبی پرسید: اسمت چیست؟\r\nآن شخص جواب داد: آدم\r\nملانصرالدین در جواب آن شخص گفت: خدا پدرش را بیامرزد آنکه این اسم را روی تو گذاشت و الا تو که قیافتاْ هیچ شباهتی به آدم نداری، مردم از کجا می فهمیدند تو آدمی.\r\n"},{"id":99,"category_id":3,"category_code":"s3","source_id":19,"title":"حرف حساب ملا ","content":" ملانصرالدین در روستا دوستی داشت. این دوست روزی به شهر و خانه ملانصرالدین آمد.\r\nآن دوست تا ملانصرالدین را دید شروع کردن به زدن خرش و خطاب به دراز گوش می گفت: ای ملعون! آرد و گندم بارت می کنم نمی آوری، روغن بارت می کنم نمی آوری، چرا می خواهی مرا نزد آشنایان خجالت دهی!؟\r\nملانصرالدین به آن فرد گفت: عبث خر بیچاره را مزن که اگر از خانه تو نتوانست برای من چیزی بیاورد از خانه من هم نمی تواند چیزی برای تو ببرد.\r\n"},{"id":100,"category_id":3,"category_code":"s3","source_id":20,"title":"دروغ ملا ","content":" پسر ملانصرالدین از خانه بیرون آمد. کسی از او پرسید: پدرت چه می کند؟\r\nپسر ملا گفت: در خانه نشسته و به خدا دروغ مي بندد.\r\nآن فرد پرسيد: چگونه؟\r\nپسر ملانصرالدين گفت: آئينه به دست گرفته و خود را در آن مي بيند و مي گويد: الحمدالله الذي احسن خلقي و خلقي(سپاس آن خداي را كه صورت و سيرت مرا نيكو ساخت)\r\n"},{"id":101,"category_id":3,"category_code":"s3","source_id":21,"title":"میراث ","content":"از ملانصرالدین وقتی کودک بود، پرسیدند: می خواهی که پدرت بمیرد تا میراث او به ارث ببری؟\r\nملانصرالدین گفت: نه به خدا، من می خواهم که او را بکشند تا چنان که ارث می برم، خون بها نیز بستانم.\r\n"},{"id":102,"category_id":3,"category_code":"s3","source_id":22,"title":"زن زشت ملا ","content":"ملانصرالدین را گول زدند و زن زشتی را به ازدواج او در آوردند. فردای عروسی ملانصرالدین خواست که از منزل خارج شود که زنش جلو آمد و با ناز دلال گفت: دوست دارم که به من بگویی، من خودم را به کدامیک از خویشانت نشان دهم و به چه کسی نشان ندهم؟\r\nملانصرالدین جواب داد: صورتت را به من نشان نده، به هر که می خواهی نشان بده.\r\n"},{"id":103,"category_id":3,"category_code":"s3","source_id":23,"title":"هوای گرم ","content":" ملانصرالدين روزگاري در شهر بغداد زندگي مي کرد. بعد از مدتي از آنجا به شهر خودش بازگشت. مردم به ديدنش آمدند و گفتند: جناب ملا! بگو بدانيم آنجا چه کار مي کردي؟\r\nملانصرالدين جواب داد: فقط عرق مي کردم!\r\n"},{"id":104,"category_id":3,"category_code":"s3","source_id":24,"title":"بوقلمون و ملا ","content":" روزی ملانصرالدین از بازار رد می‌شد كه دید عده ای برای خرید پرنده‌ی كوچكی سر و دست می‌شكنند و روی آن ده سكه‌ی طلا قیمت گذاشته‌اند. ملا با خودش گفت مثل اینكه قیمت مرغ این روزها خیلی بالا رفته. سپس با عجله بوقلمون بزرگی گرفت و به بازار برد، دلالی بوقلمونِ ملا را خوب سبك سنگین كرد و روی آن ده سكه‌ی نقره قیمت گذاشت. ملا خیلی ناراحت شد و گفت: مرغ به این خوش قد و قامتی ده سكه‌ی نقره و پرنده‌ای قد كبوتر ده سكه ی طلا؟ دلال گفت: \"آن پرنده‌ی كوچك طوطی خوش زبانی است كه مثل آدمیزاد می‌تواند یك ساعت پشت‌سر هم حرف بزند.\" ملانصرالدین نگاهی انداخت به بوقلمون كه داشت در بغلش چرت می‌زد و گفت: \"اگر طوطی شما یك ساعت حرف می‌زند در عوض بوقلمون من دو ساعت تمام فكر می‌كند.\""},{"id":105,"category_id":3,"category_code":"s3","source_id":25,"title":"احوال پرسي ملا ","content":"ملا به بالین بیماری رفت تا حال و احوالی از او بپرسد. مریض در جواب ملا كه از حالش پرسیده بود گفت: تب شدیدی داشتم و گردنم هم سخت به درد آمده است ولی خدا را شكر تب دو روز است شكسته اما گردنم دو روز است درد میكند. ملا فكری كرد و گفت: غصه نخور من دعا می كنم آن هم تا دو روز دیگر بشكند."},{"id":106,"category_id":3,"category_code":"s3","source_id":26,"title":"ملا و پياده رفتن ","content":" ملا خرش را جلو گذاشته و خودش با وجود آنكه باری بر روی بدن الاغ نبود سوار نشده و پیاده از دنبالش حركت میكرد. شخصی این صحنه را دید و پرسید: برای چه سوار الاغ نمیشوی و پیاده میروی؟ ملا گفت: مگر من از این الاغ كمتر ام كه آن پیاده برود ولی من سوار شوم."},{"id":107,"category_id":3,"category_code":"s3","source_id":27,"title":"ملا و قصاص ","content":" در هنگام قضاوت دختری نزد ملا آمده از جوانی شكایت كرد كه او را به زور بوسیده است. ملا گفت: راءی من قصاص به مثل است. تو هم به زور او را ببوس\r\nشنا ياد دادن ملا - چند روزی بود كه از ملا خبری نبود و كسی او را در كوچه و بازار نمی دید. مردم نگران شده بودند یكروز به خانه وی رفتند و وقتی وارد شدند دیدند ملا در كنار حوض خانه ایستاده و تكه نخی به گردن جوجه مرغابی بسته و آنرا اینطرف و آنطرف میكشاند. دوستانش پیش رفته و پرسیدند: جناب ملا كجا استی بابا... چند روز است از تو خبر نداریم.\r\nملا اشاره ای به جوجه مرغابی داخل حوض كرده و گفت: چیزی نیست دوستان مادر این جوجه مرغابی چند روز قبل مرده و من برای این كه شنا یادش بدهم ناچار شده ام در خانه بمانم چون میترسم اگر شنا بلد نباشد یكروز وقتی من نیستم در حوض آب افتاده و بمیرد.\r\n"},{"id":108,"category_id":3,"category_code":"s3","source_id":28,"title":"ملا و آواز خواني پسرش ","content":"پسرملا در شب آواز میخواند. همسایه از بام سر بر آورده گفت: موقع خواب است دیگر آواز نخوان. ملا گفت: عجب مردمان پر روئی هستید. شب و روز سگ های شما عوعو میكند من یك دفعه اعتراض نكردم شما نتوانستید چند دقیقه ای آواز خواندن پسر مرا تحمل كنید."},{"id":109,"category_id":3,"category_code":"s3","source_id":29,"title":"خرما خوردن ملا ","content":" ملا مقداری خرما خرید و همینطور با خسته مشغول خوردن خرماها بود. زنش كه آن صحنه را دید پرسید كه چرا خرما را با هسته میخوری. ملا گفت: مگر دكان خوراكه فروشی سر كوچه خرما ها را بدون هسته به من فروخته كه من هم آنها را بی هسته بخورم؟"},{"id":110,"category_id":3,"category_code":"s3","source_id":30,"title":"ملا و ظرف سوراخ ","content":" ملا ظرف كهنه ای را به بازار برد كه بفروشد. چون سوراخ بود مشتری ای پیدا نكرد. یكی گفت: این ظرف میانش كه چیزی بند نمیشود. چه كسی آنرا میخرد؟ ملا متحیرانه گفت: زن من این ظرف را پر از پنبه كرد یك ذره ی آن نریخت. چطور تو میگوئی چیزی در آن بند نمیشود؟"},{"id":111,"category_id":3,"category_code":"s3","source_id":31,"title":"ملا و آواز از دور ","content":"ملا در صحرا با صدای بلند آواز خوانده و میدوید. عابری پرسید: ملا اگر میخوانی پس دویدنت برای چیست؟ ملا جواب داد: میگویند آواز من از دور خوش است. میدوم تا آواز خود را از دور بشنوم."},{"id":112,"category_id":3,"category_code":"s3","source_id":32,"title":"ملا و گاديوان ","content":" یك روز ملا از سفری بر میگشت و مقدار زیادی بار با خود آورده بود. وقتی در ایستگاه از موتر پایین شد و بارهایش را روی زمین نهاد و گادیوانی را صدا زد و آدرس خانه خود را به او داد و گفت: خوب كاكاجان حالا بگو چند میگیری كه خودم و بار ها را به آدرسی كه گفتم برسانی؟ گادیوان گفت: برای بردن خودت پنج دینار ولی برای بردن بارها هیچ. ملا فكری كرد و گفت: بسیار خوب پس بارها را به آدرسی كه گفتم ببر من خودم پیاده خواهم آمد."},{"id":113,"category_id":3,"category_code":"s3","source_id":33,"title":"بغداد رفتن ملا ","content":" روزی مردی نزد ملا آمده و به وی گفت: جناب ملا خواهش دارم نامه ای برای دوست من كه در بغداد است بنویس. ملا سرش را جنباند و گفت: برو برادر.... من آنقدر كار دارم كه دیگر فرصتی برای رفتن به بغداد برایم باقی نمانده است. مرد مذبور كه متوجه مقصود ملا نشده بود گفت: ولی جناب ملا من از شما خواستم كه فقط كاغذی به دوستم كه در بغداد زندگانی میكند بنویسید دیگر نگفتم كه به آنجا بروید. ملا لبخندی زد و گفت: میدانم و من هم به همین دلیل گفتم وقت ندارم به بغداد بروم چون خط من به قدری بد است كه اگر كاغذ برای دوست تو بنویسم ناچارم خودم هم به دنبال آن بروم تا در بغداد نامه را برای او بخوانم."},{"id":114,"category_id":3,"category_code":"s3","source_id":34,"title":"عرعر كردن خر ملا ","content":" ملا مقداری پیاز بار خر خود كرده و در كوچه و بازار شهر میگشت. ولی هر بار كه میخواست فریاد بزند و مردم را از خوبی و ارزانی پیاز هایش باخبر كند خرش شروع به عرعر كردن مینمود و نمیگذاشت ملا فریاد بزند. ملا چند بار خواست فریاد بزند ولی با عرعر خر روبرو شد و سرانجام عصبانی شد و خطاب به خر خود گفت: ببینم آیا تو پیاز ها را میفروشی یا من؟"},{"id":115,"category_id":3,"category_code":"s3","source_id":35,"title":"ملا و غاز يك پا ","content":" روزی ملانصرالدین غاز پخته ای برای حاكم تازه وارد هدیه میبرد اما در بین راه گرسنه اش شد و یك ران غاز را خورد به بقیه بدن حیوان را برای حاكم برد\r\nحاكم وقتی غاز را با یك پا دید پرسید: خوب پس یك پای دیگر این حیوان كجاست؟ ملا گفت: قربان در شهر ما غاز بیشتر از یك پا ندارد، اگر باور نمیكنی غاز هایی را كه در كنار حوض منزل تان ایستاده اند مشاهده كنید.\r\nحاكم به كنار پنجره آمد و به كنار حوض نگریست اتفاقا چند غاز به روی یك پای خویش ایستاده و به خواب فرو رفته بودند. ملا با خوشحالی گفت: نگفتم قربان غاز های این شهر بیشتر از یك پای ندارند. اما در همان وقت چند نفر از غلامان آمده و با چوب به غاز ها زدند تا از آنجا به لانه های خود بروند و غاز ها با هر دو پای خود شروع به دویدن كردند. حاكم رویش را به طرف ملا كرد و گفت: حال دیدی كه تو دروغ میگفتی و غاز ها دو پا دارند. ملا فكری كرد و گفت: چوبی را كه آنها نوش جان كردند اگر به بدن شما هم میزدند به جای دو پا چهار پا میشدی و فرار میكردی.\r\n"},{"id":116,"category_id":3,"category_code":"s3","source_id":36,"title":"ملا و اندازه دنيا ","content":" روزی جمعی در كوچه جلو ملا را گرفته پرسیدند دنیا چند ذرع است؟\r\n. قبل از اینكه ملا جواب دهد جنازه ای از آنجا عبور دادند\r\nملا تابوت را نشان داده گفت: این مسئله را از این شخص بپرسید كه دنیا را ذرع كرده و میرود.\r\n"},{"id":117,"category_id":3,"category_code":"s3","source_id":37,"title":"جنگ ملا ","content":" یك شب ملا وقتی میخواست بخوابد شمشیر بلندی را كه به دیوار اطاقش آویزان بود برداشته و به كمر بست. زنش پرسید چه میكنی و برای چه هنگام خواب شمشیر میبندی؟ ملا گفت: شب گذشته در خواب با مردی دعوایم شد و او برایم شمشیر كشید و چون من اسلحه نداشتم شكست خوردم حالا من هم این شمشیر را به كمرم بسته ام تا چنانچه باز هم او را در خواب دیدم انتقام خود را از او بگیرم و با این شمشیر حسابش را برسم."},{"id":118,"category_id":3,"category_code":"s3","source_id":38,"title":"ملا و غلام ","content":"ملا غلامی خرید، گفتند: عیب او این است كه شبها در بسترش میشاشد. ملا گفت: اگر بستر یافت مختار است هر چه خواست در آن بكند."},{"id":119,"category_id":3,"category_code":"s3","source_id":39,"title":"دوري ملا ","content":"روزی ملا پهلوی زنش نشسته بود. زنش به ملا گفت اگر كمی دور بشینی بهتر خواهد شد. ملا برخاسته خرش را بیرون كشیده سوار شده و به یك ده در پنج فرسخی رفت و از آنجا نامه ای برای زنش نوشت وپرسید: تا این حد دوری خوب است یا دورتر برم؟"},{"id":120,"category_id":3,"category_code":"s3","source_id":40,"title":"جسارت ملا ","content":" حاكم میخواست شخص جسوری را به ماموریت خطرناكی بفرستد. كسی را نیافت. ملا گفت: من برای رفتن به این ماموریت حاضر هستم. حاكم تصور كرد ملا شوخی میكند گفت: باید جسارتت را امتحان كنیم. پس امر كرد او در جایی ایستاده و دو دست خود را باز كند و به یكی از كمانداران نامی گفت: میخواهم عمامه ملا را با تیر نشان سازی\r\nتیرانداز شب كلاه عمامه را سوراخ كرد. ملا از ترس نزدیك بود قالب تهی كند ولی به روی خود نیاورد. مرتبه دوم حاكم به تیرانداز دیگری امر كرد كه چپن ملا را سوراخ سازد. او هم تیر به دامن لباس ملا زده سوراخ نمود. ملا رنگ خود را باخت و بی اندازه ترسید. چون تجربه به پایان رسید، نزد حاكم آمد. حاكم دستور داد یك عمامه و یك قبای نو به ملا بدهند\r\nملا با خوشحالی خواهش كرد یك پتلون نو هم ضمیمه نمایند. حاكم گفت: پتلون شما كه سوراخ نشده. ملا جواب داد: ظاهرا صدمه ای ندیده ولی در حقیقت پیش از عمامه و قبا تر شده.\r\n"},{"id":121,"category_id":3,"category_code":"s3","source_id":41,"title":"ملا و مرد مست ","content":" یكشب ملا به طرف خانه اش میرفت كه مرد مستی به وی تصادف كرد. ملا برگشت و گفت: احمق مگر كور استی كه آدم به این بزرگی را نمی بینی؟ مرد مست در حالی كه از مستی پس و پیش میشد گفت: اتفاقا به جای یكی دوتا میبینم. ملا گفت: خوب پس چرا با من تصادف میكنی؟ مرد مست گفت: چون من میخواستم از وسط شما دوتا رد بشوم."},{"id":122,"category_id":3,"category_code":"s3","source_id":42,"title":"زن گرفتن ملا ","content":"پس از مرگ زنش ملا چند نفر از همسایه ها را جمع كرده و از آنها خواهش كرد زنی برای او پیدا كنند كه دارای چهار صفت باشد. 1 دختر باشد. 2 پولدار باشد. 3 زیبا باشد. 4 خوش اخلاق باشد. یكی از زنان همسایه گفت: ملا صفاتی كه شما میخواهید در یك زن جمع نمیشود, بهتر است اجازه بدهید چهار زن برای شما بگیریم كه هر یك دارای یكی از این صفات باشند. ملا جواب داد: اگر چه علاقه داشتم كه چهار صفت در یك زن جمع باشد ولی حالا كه شما صلاح میدانید مانعی ندارد. چهار زن تهیه كنید ولی سعی كنید هر یك در صفت خود بینظیر باشد."},{"id":123,"category_id":3,"category_code":"s3","source_id":43,"title":"آتش روشن كردن ملا","content":" یك روز وقتی زن ملا در خانه نبود او تصمیم گرفت به آشپزخانه رفته و خودش غذایی درست كند. ملا پس از این فكر وارد آشپزخانه شده و مقداری هیزم به داخل اجاق گذاشت و خواست آنرا آتش بزند ولی هر كاری كرد هیزم ها آتش نگرفت. ملا فكری كرد و ناگهان گفت: هان.... حالا فهمیدم برای چه آتش روشن نمیشود. هیزم های ناجوان فهمیده اند كه من زن خانه نیستم. و آشپزی كار من نیست. این است كه روشن نمیشوند...... بسیار خوب من هم میدانم چه تخنیكی بر سر آنها بزنم و چگونه فریبشان بدهم. او پس از این فكر به اطاق دیگری رفته و یكی از روسری های همسرش را برداشت و آنرا بر سر خود كرده و به آشپزخانه آمد و مشغول روشن كردن آتش شد. اتفاقا هیزم ها روشن شد و آتش خوبی درست شد. در همان وقت زن ملا به خانه آمد و وقتی شوهرش را در آن حالت دید با تعجب پرسید: ملا، برای چه روسری بر سرت بسته ای؟ ملا به آهستگی گفت: آرام باش.... من هیزم ها را فریب داده ام و آنها خیال میكنند زن هستم وگرنه روشن نمیشدند. در همان هنگام ناگهان جرقه ای پرید و بر روی لباس ملا افتاد و آن را آتش زد. ملا وحشت زده از كنار اجاق دور شده و در حال كه سعی میكرد لباسش را خاموش كند فریاد زد: زن از بس حرف زدی بالاخره آتشها فهمیدند فریبشان داده ام..."},{"id":124,"category_id":3,"category_code":"s3","source_id":44,"title":"ملا در قبرستان ","content":" ملا بر قبرستان رفته بود و بر سر قبری بی حد گریه میكرد. راهگذری تصور كرد ملا سر قبر پسرش است كه اینطور زار میگرید و میگوید چرا به من رحم نكردی و به این زودی مردی. پس جلو آمده خواست او را تسلیت دهد. از ملا پرسید: قبر پسر ناكام شماست كه اینطور متاثر هستید؟ ملا گفت: خیر، قبر شوهر اول عیال من است كه مرده و این بلای ناگهانی را به جان من انداخته و زندگی را به كام من تلخ كرده."},{"id":125,"category_id":3,"category_code":"s3","source_id":45,"title":"اختيار با اوست ","content":" ملا سوار قاطر شده به راهی میرفت. ناگاه قاطر او را برداشته از راه دیگری شروع به رفتن نمود. یكی از رفقا با تعجب پرسید: ملا كجا میروی؟ ملا گفت: عجالتا اختیار من با این قاطر است. هر جا میلش باشد مرا خواهد برد."},{"id":126,"category_id":3,"category_code":"s3","source_id":46,"title":"انگشتر ","content":" شخصی به ملا گفت: انگشترت را به من بده تا هر وقت آنرا ببینم به یاد تو بیفتم.\r\nملا گفت: انگشتر را نمیدهم. و تو هر وقت انگشتت را نگاه كردی یاد بیاور كه انگشتر را از من خواستی من ندادم.\r\n"},{"id":127,"category_id":3,"category_code":"s3","source_id":47,"title":"حماقت ملا ","content":" روزی ملا چاینك بسیار قشنگی خرید و به طرف خانه اش رفت. اما در بین راه با خود فكر كرد خوب اگر این چاینك در خانه به زمین بخورد و بشكند آنوقت من از كجا یك چینی بند زن پیدا كنم تا تكه های آنرا بند بزند؟ او قدری در این باره فكر كرد و سرانجام با خود گفت: بسیار خوب پس بهتر است حالا كه در بازار هستم چینی بند زن هم در اینجا است چاینك را خودم بشكنم و بدهم بند بزند.\r\nاو پس از این حرف چاینك را به زمین زد و تكه های آنرا برداشته و بطرف چینی بند زنی كه در آن نزدیكی بود رفت و از وی خواست تا آنرا بند بزند.\r\n"},{"id":128,"category_id":3,"category_code":"s3","source_id":48,"title":"ملا و مرد زورآور ","content":" یكروز ملا از راهی میگذشت. چشمش ندید و سیلی محكمی به مرد زورآوری كه از كنارش میگذشت زد. مرد رویش را برگشتاند و چند دشنام به او داد. ملا قدری ایستاد و به مرد مزبور نگریست. آنوقت دو قدم به طرفش برداشت و گفت: به من دشنام میدهی؟ مرد زورآور دو قدم به طرفش برداشت و گفت: نخیر به بابا و ننه ات دشنام میدهم. ملا دو قدم عقب رفته و گفت: ببخشید خیال كردم به من دشنام میدهید."},{"id":129,"category_id":3,"category_code":"s3","source_id":49,"title":"ملا و ماه كهنه ","content":" شخصی از ملا سئوال كرد : این ماهی كه هر ماه نو می شود، كهنه ی آن را چه می كنند؟\r\nملا در جواب گفت:ای احمق، هنوز این مطلب را نفهمیده ای؟ ماه های كهنه را خرد می كنند و با آن این ستاره ها را می سازند كه در آسمان است.\r\n"},{"id":130,"category_id":3,"category_code":"s3","source_id":50,"title":"دزديدن خر ملا ","content":" خر ملا را یكشب از طویله دزدیده و بردند. روز بعد وقتی ملا از جریان باخبر شد شروع به جستجو كرد تا شاید آنرا بیابد و برای یافتن وی از همسایگان میپرسید كه آیا خرش را دیده اند یا نه. همسایه ها وقتی فهمیدند خر ملا دزدیده شده شروع به ملامت وی كردند.\r\n یكی گفت چرا در طویله را باز گذارده ای. دیگر گفت برای چه مواظبت نكردی تا دزد نتواند خرت را ببرد و سومی میگفت چرا خوابت آنقدر سنگین است كه نتوانستی از شنیدن صدای باز شدن در طویله بیدار شده و دزد را دستگیر كنی، ملا كه تمام این حرف ها را میشنید و دیگر عصبانی شده بود، ناگهان فریاد زد: پس اینطور كه شما میگوئید تمام گناهان به گردن من است و دزد كاملا حق به جانب است.\r\n"},{"id":131,"category_id":3,"category_code":"s3","source_id":51,"title":"احمق تر از ملا ","content":" از ملا پرسیدند آیا احمق تر از خودت دیده ای، گفت بلی, یك روز نجاری را به خانه آوردم تا دروازه ای برای اتاقهایم بسازد. نجار متر با خود نداشت تا اندازه در را بگیرد، این بود كه دو دست خود را به دو طرف دراز كرده و به این وسیله اندازه در را معین كرد. او پس از این كار به همان حالت از خانه خارج شد و در راه مراقب بود با كسی بر خورد نكرده و اندازه دستش به هم نخورد. او در حالی كه سرش را بالا گرفته و به زیر پایش توجهی نداشت به طرف دكانش میرفت كه اتفاقا به داخل چاهی كه در سر راهش قرار داشت افتاد. اما چاه عمق زیادی نداشت. مردم به اطراف چاه جمع شده و گفتند دستت را بالا بیاور تا ترا از داخل چاه خارج كنیم. اما مرد نجار گفت: دستم را نمیتوانم بالا بیاورم چون اندازه دروازه بهم میخورد، ریشم را بگیرید."},{"id":132,"category_id":3,"category_code":"s3","source_id":52,"title":"ملا و دفينه ی بو","content":" ملا كوزه پولی در خرابه دفن كرده هر وقت پول نقدی به دست میاورد در آن میریخت و حساب آنرا میداشت. عطاری در مقابل خرابه دكان داشت. او از آمد و رفت ملا مشكوك شده برای كشف قضیه به خرابه رفته محل دفینه را یافت و پول ها را كه چهل و یك دینار بود شمرده برداشت و پی كار خود رفت. روز دیگر ملا سر دفینه رفته پول را ندید دانست عطار دستبرد زده.\r\n از آنجا رد شد دید عطار در دكانش نیست. پس تدبیری اندیشیده ساعتی بعد نزد عطار رفت و گفت: خواهش دارم چند قلم برایم بنویسی و جمع بزنی. عطار گفت: بفرما. ملا گفت: بنویس سی و شش دینار و به آن اضافه كن هفتاد و دو دینار جمع آن میشود صد و هشت دینار با چهل و یك كه جمع كنیم صد و چهل و نه دینار میشود و یك دینار میخواهد تا صد و پنجاه دینار شود. ممنونم و خدا حافظی كرده روان شد. عطار گمان كرد ملا دو جای دیگر پول دارد و میخواهد به چهل و یك دینار اضافه كند. با شتاب پولها را برده به جای خودش گذاشت. ملا روز بعد به خرابه رفته مدتی طول داد. چون بیرون آمد عطار به سر دفینه رفت به جای پول دید نجاست ریخته اند.\r\nملا كه مراقب بود وقتی او را دید كه از خرابه بیرون آمد پیشش رفته گفت: دستت را بو كن ببین چه بوئی میدهد؟\r\n"},{"id":133,"category_id":3,"category_code":"s3","source_id":53,"title":"ملا و نمونه تيراندازي ","content":"روزی بزرگان شهر با حاكم در بیرون شهر به تیر اندازی مشغول بودند. حاكم امر كرد همه بایستی هنر خود را بنمایانند. به ملا كه نوبت رسید تیری در كمان گذاشته رها كرد ولی به نشانه نخورد. گفت: پدرم اینطور تیر می انداخت.\r\nمرتبه ی دوم تیر انداخت به نشانه نخورد. گفت: برادرم اینطور تیر می انداخت.\r\nدر مرتبه ی سوم اتفاقا تیر به نشانه خورد. گفت: خودم همیشه اینطور تیر می اندازم.\r\n"},{"id":134,"category_id":3,"category_code":"s3","source_id":54,"title":"الاغ فروختن ملا ","content":" روزی ملا كه مدتی بود بی پول شده بود تصمیم گرفت الاغش را به شهر برده بفروشد. زنش وقتی این تصمیم ملا را دید گفت: مگر دیوانه شده كه الاغ را بفروشی با چه وسیله ای كار های خود را انجام میدهی و به اینطرف و آنطرف میروی؟ ملا لبخندی زد و گفت: خیالت راحت باشد زن، من قیمتی به روی آن میگذارم كه هیچ كس نتواند بپردازد."},{"id":135,"category_id":3,"category_code":"s3","source_id":55,"title":"ملا و رقابت زنها ","content":"ملا نزد رفیقش رفته گفت: خیلی دلم برایت میسوزد. رفیقش پرسید: به چه سبب؟ ملا جواب داد: امروز من بعد از مرافعه ها كه نزدیك بود به طلاق بكشد به بازار رفته برای زنم جوراب و پیراهن و كفش نو خریدم. رفیقش گفت: به من چه ربطی دارد؟ ملا جواب داد: زن تو با زن من رفت و آمد دارد. قطعا وقتی جوراب و پیراهن و كفش نو را به پای زن من ببیند تكلیف معلوم است. رفیق ملا كه وخامت كار را فهمید فورا در صدد تهیه ی پول برآمد."},{"id":136,"category_id":3,"category_code":"s3","source_id":56,"title":"كسب ملا ","content":"ملا كمتر حاضر میشد به خاطر طلب روزی از خانه خارج شود. روزی زنش به او گفت: از این به بعد اگر همه روزه صبح از خانه بیرون نرفته و تا غروب اقلا بیست دینار نیاوری به خانه راهت نمیدهم. ملا ناچار از خانه خارج شد و تا غروب آفتاب، هر چه تلاش كرد چیزی نیافت. از ترس زن به خانه نرفت و به خرابه ای كه نزدیك بود رفته در زاویه ای خزیده فكر میكرد كه زندگی با این ترتیب خیلی مشكل است. در این اثنا درویشی وارد خرابه شده در گوشه ای ادرار گرفت و پس از رفع خستگی كوله پشتی خود را جلو گذاشته چراغی افروخت و قدری موم بیرون آورده صورتی با آن ساخته در مقابل گذاشت و او را آدم نامید و به او خطاب كرده گفت: خداوند تو را آفرید و در بهشت جا داد و همه نوع نعمت خود را بر تو ارزانی داشت و تنها تو را از خوردن گندم منع كرد. گندم را خوردی تا تو را از بهشت بیرون كرده به دنیا انداخت و ما از نسل تو به وجود آمدیم و باید تا زنده ایم برای كسب روزی همیشه با شرارت و غصه بوده و وقتی كه مردیم به دلیل گناه هائی كه مرتكب شده ایم در عذاب باشیم.\r\n درویش این را گفت سپس با عصای خود به سرش زده و آنرا درهم شكست و دو باره صورتی ساخته او را حوا نامیده و گفت: ای حوا، تو از بهشت چشم پوشیده، آدم را به خوردن گندم وادار ساختی و باعث تولید مثل ها شده و همه را دچار بدبختی نمودی. پس عصائی به سرش زده او را هم درهم شكست. و باز صورت دیگری ساخته او را شیطان نامیده و گفت: ای ملعون تو كه مقرب بودی چرا از حد خود تجاوز كرده خلاف امر خداوند نموده به آدم سجده نكردی و تا ترا به اسفل السافلین انداختند. دوباره چرا آدم را وسوسه نموده به خوردن گندم وادار كردی و از سر اولاد او هم دست بر نداشته پیوسته آنها را اغوا مینمائی. پس عصائی بر سر او هم زده او را هم در هم شكست و همچنان از آن موم صورتها ساخته هر یك را به اسم یكی از انبیاً یا اولیاً موسوم نموده بهانه ای بر او گرفته نابودش میكرد.\r\nتا آنكه در آخر همه صورتی ساخته آنرا رب اعلا نامید و شروع كرد به او عتاب و خطاب كردن و بر او تقصیر گرفتن و چون خواست عصا بر سر او زند ملا از جا برخاسته فریاد زد: صبر كن من بیست دینار از او بگیرم بعد خراب كن و اگر عجله كنی بیست دینار از تو خواهم گرفت. چون زنم بی پول به خانه راهم نمیدهد. درویش فریاد ملا را متوجه شده از ترس كوله پشتی خود را به جا گذاشته فرار كرد. ملا اسباب او را تصاحب كرده در میان اثاثیهً مختلف پنج صد دینار پول نقد یافت. رو به خانه رفت و چون درب زد زنش پشت درب آمده گفت:\r\nاگر بیست دینار آورده ای درب را میگشایم ورنه برو پی كارَت. ملا جواب داد:\r\nاحمق درب را بگشا كه به جای بیست دینار پنج صد دینار آورده ام. زن درب را باز كرده دید ملا راست میگوید از او پرسید: این پول را از كجا بدست آورده \r\n"},{"id":137,"category_id":3,"category_code":"s3","source_id":57,"title":"گريه و خنده ","content":" یك نفر قطب نمایی پیدا كرده بود و چون نمیدانست آن چیست به نزد ملا آمده قطب نما را نشان وی داد و پرسید كه آن چه میباشد. ملا نگاهی به قطب نما كرده و بلافاصله شروع كرد به گریه كردن. اما چند دقیقه بعد بدون درنگ دست از گریه برداشت و شروع به خنده كرد. مرد مزبور با تعجب پرسید: برای چه گریه كردی و به چه جهت خندیدی؟ ملا سرش را جنباند و گفت: گریستنم برای این بود كه تو چقدر نادان هستی كه نمیدانی چیز به این كوچكی چه میباشد. خندیدنم برای آن بود كه چون خوب دقت كردم متوجه شدم كه خودم هم نمیدانم این چیست."},{"id":138,"category_id":3,"category_code":"s3","source_id":58,"title":"در خانه نبودن ملا ","content":" ملا در کنار پنجره خانه اش نشسته و به کوچه و عابرینی که از میان آن میگذشتند نگاه میکرد. ناگهان مردی را دید که به طرف خانه وی میآید. ملا آن مرد را به خوبی میشناخت و میدانست برای وصول پولی که از ملا میخواهد آمده.\r\nملا فورا زنش را خواسته و در گوش او چیز هایی گفت و آن وقت منتظر مرد طلبکار باقی ماندند. چند دقیقه ای بعد در خانه به صدا در آمد و زن ملا بلافاصله آنرا گشود و به مرد طلبکار که در پشت دروازه ایستاده بود گفت: آقا من نمیدانم که شما چند سال است برای طلب خود به اینجا میآیید ولی اطمینان داشته باشید ما مال مردم خوار نیستیم و به زودی طلب شما را خواهیم پرداخت و هر چند که جناب ملا خودش خانه نیست اما به من سفارش کرده هر روز در کنار دروازه خانه ایستاده شوم و منتظر باشم تا گوسفند های که به بازار برده میشوند از کنار خانه ما بگذرند. آنوقت خرده های پشم آنها را که به روی زمین ریخت جمع نمایم و شال گردن ببافم و آنها را به بازار برده بفروشیم و پول شما را بپردازیم. مرد طلبکار وقتی این حرف را شنید و دانست طلبش به این زودی ها وصول نمیشود از شدت عصبانیت خنده اش گرفت و شروع به خندیدن کرد.\r\nملا نیز در پشت سر زنش پنهان شده بود وقتی خنده های مرد مزبور را دید او هم به خنده افتاد و در حالی که با صدای بلندی میخندید جلو آمده و گفت: ای پدر سوخته باید هم بخندی چون حالا دیگر اطمینان پیدا کرده ای که طلبت به طور حتمی وصول میشود.\r\n"},{"id":139,"category_id":3,"category_code":"s3","source_id":59,"title":"به قاضي ميرسد ","content":"دو همسایه با هم نزاع كرده پیش قاضی آمده هر یك ادعا مینمودند كه لاشه سگ مرده كه در كوچه افتاده به خانه هر كس نزدیكتر است او باید از كوچه آنرا بردارد. اتفاقاَ ملا در محضر قاضی بود قاضی به او گفت در این مورد نظر شما چیست؟ ملا گفت كوچه راه عام است به هیچكدام ربط ندارد این وظیفه قاضی است كه باید لاشه سگ را از میان كوچه بردارد."},{"id":140,"category_id":3,"category_code":"s3","source_id":60,"title":"انجام وظيفه ملا","content":" ملا در باغ خود مشغول كاشتن نهالهای كوچك بود عابری پرسید به چه طمع به كاشتن این درختها مشغولی؟\r\nو تصور میكنی چند سال دیگر عمر مینمائی كه ثمر این درختها را بخوری؟\r\nملا با كمال وقار گفت: ای نادان دیگران كاشتند میوه آن نصیب ما شد ما می كاریم تا آیندگان از آن استفاده كنند.\r\n"},{"id":141,"category_id":3,"category_code":"s3","source_id":61,"title":"ملا و صرفه جوئي ","content":" یك روز دوستان ملا او را دیدند كه یك دست و یك چشم و یك پا و یك سوراخ بینی و یك گوش خود را بسته است. به خیال این كه مریض میباشد شب به خانه اش رفته و با دلسوزی گفتند: خدا بد ندهد.... جناب ملا، بلا دور...باشد چه شده و برای چه دست و پایت و سرو چشمت را بسته ای؟\r\n ملا لبخندی زد و گفت: من كاملا سالم هستم. مگر برای اینكه صرفه جوئی كنم و اعضای بدنم را بی جهت به كار نیاندازم نیمی از آنها را بسته ام.\r\n"},{"id":142,"category_id":3,"category_code":"s3","source_id":62,"title":"مهر ","content":"ملا میخواست مهری برای پسرش بكند كه نام پسرش بر روی آن نوشته شده باشد.\r\n در آن شهر مرد حكاكی زندگی میكرد كه برای كندن هر حرف در روی مهر یك دینار میگرفت. ملا به نزد وی رفته و گفت: جناب حكاك من میل دارم مهری برایم بكنی كه نام پسرم بر رویش نوشته شده باشد. مرد حكاك گفت: قیمت كار مرا كه میدانی برای هر حرف یك دینار باید بپردازی. ملا سرش را جنباند و گفت: بلی\r\nمرد حكاك گفت: خوب اسم پسرت چیست؟ ملا فكری كرد و گفت: (خس) مرد مزبور گفت: دو دینار باید بدهی\r\nملا دو دینار داد و حكاك شروع به كار كرد و پس از چند دقیقه ای كلمه (حس) را روی مهر كند و نوبت نطقه ای رسید كه باید روی (ح) بگذارد كه ملا دست وی را گرفته گفت: جناب حكاك خواهش دارم نقطه را به جای آنكه در سر (ح) بگذاری در داخل شكم (س) بگذار حكاك آن كار را كرد و كلمه (حسن) در روی مهر نقش بست و ملا مهر را گرفته و گفت: من به جای سه كلمه پول دو كلمه را دادم جناب حكاك باشی زرنگ.\r\n"},{"id":143,"category_id":3,"category_code":"s3","source_id":63,"title":"چاره جويي ملا","content":" روزی گاوی برای خوردن آب سرش را داخل خمره بزرگی كه پر از آب بود كرد. اما دیگر نتوانست آنرا از داخل خمره خارج كند. مردم به دور حیوان و خمره جمع شدند\r\nاما هر چه كردند نتوانستند سر گاو را از خمره بیرون آورند. از قضا ملا از آنجا میگذشت مردم وقتی وی را دیدند دست به دامانش شدند تا راه چاره ای نشان بدهد. ملا گفت: زود باشید سر گاو را ببرید تا خفه نشده و گوشتش حرام نشود.\r\n بلافاصله قصابی آوردند و گردن گاو را بریده و تنه اش را جدا كردند. اما سر گاو به داخل خمره رفته و دیگر بیرون نمی آمد. پرسیدند جناب ملا حالا چی كار كنیم؟ ملا باز هم فكری كرده گفت: چاره ای نیست باید خمره را بشكنید و سر گاو را از داخلش بیرون بیاورید.\r\n"},{"id":144,"category_id":3,"category_code":"s3","source_id":64,"title":"ملا و انگشتر بي نگين ","content":" امیری انگشتر بی نگینی به ملا هدیه كرد. ملا به جایش دعا كرد كه خدا در بهشت خانه ای بی سقف به او عنایت فرماید. امیر پرسید: چرا خانه ی بی سقف؟ ملا جواب داد: هر وقت نگین انگشتر رسید سقف خانه هم ساخته خواهد شد."},{"id":145,"category_id":3,"category_code":"s3","source_id":65,"title":"هوش زن ملا ","content":" زن ملا از او پرسید: دزد چطور به خانه انسان میاید؟ ملا گفت: كف پاهای خود را نمد پیچیده طوری راه میرود كه صدای پایش شنیده نشود.\r\n شبی زن ملا خوابش نبرد. نیمه شب با عجله ملا را بیدار كرد. ملا پرسید: چه خبر است؟ زن گفت: گمان دارم دزد امده. ملا گفت: از كجا میدانی؟ زن گفت: مدتی است بیدارم هر چه گوش دادم صدائی نشنیدم یقین كردم دزد با پاهای نمد پیچ آمده.\r\n"},{"id":146,"category_id":3,"category_code":"s3","source_id":66,"title":"كدام حرفت را باور كنم ","content":" یك روز ملا به زنش گفت قدری پنیر بیاور كه بخوریم چون شنیده ام پنیر اشتها را زیاد میكند و نیروی بسیاری دارد و برای بدن خیلی مفید است. زن ملا گفت: ولی ما پنیر در خانه نداریم. ملا بلادرنگ اظهار داشت: بهتر چون پنیر خون را كثیف كرده و چربی بدن را افزایش میدهد و هیچ ثمری ندارد.\r\n زن ملا كه از این ضد و نقیض گوئی شوهرش در تعجب فرو رفته بود گفت: چه میگویی مرد، حرف اول ات را باور كنم یا آنچه را بعدا گفتی؟ ملا گفت: اگر پنیر در خانه داشتیم حرف اول را ولی حالا كه نداریم حرف دوم.\r\n"},{"id":147,"category_id":3,"category_code":"s3","source_id":67,"title":"گوساله ملا","content":" در صحرا ملا خواست گوساله اش را گرفته به خانه ببرد. گوساله آنقدر خیز و جست كرده فرار كرد كه ملا خسته شد پس ملا او را گذاشته به خانه رفته چوبی برداشته شروع كرد به زدن مادر گوساله!\r\nزنش جلو آمده پرسید: چرا گاو را میزنی، مگر دیوانه شده ای؟ ملا گفت: از بس حرام زاده است یكساعت با گوساله اش تلاش كرده نتوانستم او را بگیرم و به خانه بیاورم. اگر این گاو خیزك زدن و گریختن را به او یاد نمیداد گوسالهً شش ماهه مرا اینقدر اذیت نمیكرد.\r\n"},{"id":148,"category_id":3,"category_code":"s3","source_id":68,"title":"طمع ملا ","content":"ملا از كنار تالابی میگذشت كه ناگهان متوجه شد مرغابی ای به هوا پرید. ملا بلافاصله دامن لباس اش را بالا گرفت و به دنبال مرغابی شروع به دویدن كرد\r\nچند نفری وی را در آن حال دیدند و پرسیدند برای چه دنبال مرغابی میدود.\r\nملا اظهار داشت: ممكن است مرغابی تخمی بیندازد و چه بهتر كه آن در دامن من بیفتد نه بر زمین.\r\n"},{"id":149,"category_id":3,"category_code":"s3","source_id":69,"title":"ملا و دروازه مسجد","content":" دروازه خانه ملا را دزدان دزدیده بودند. ملا هم رفت دروازه مسجد را كند و به خانه آورد. پرسیدند: چرا چنین كردی؟ ملا گفت: دروازه خانه مرا دزد برده وخداوند این دزد را میشناسد. خداوند دزد را به من بسپارد و و دروازه خانه اش را پس بگیرد."},{"id":150,"category_id":3,"category_code":"s3","source_id":70,"title":"دفع سگ ","content":" به ملا گفتند: اگر به سگ درنده ای مصادف شدی آیهً اصحاب كهف را بخوان سگ فرار میكند. ملا گفت: چون همه سگها قرآن نمیفهمند برای دفع آنها یك چوب محكم لازم است."},{"id":151,"category_id":3,"category_code":"s3","source_id":71,"title":"غيبگوئي و ملا ","content":" یك روز ملا مقداری زردآلو از درختی چیده و در دستمال خود گذاشته و به سوی خانه اش میرفت. \r\nدر راه چند نفر را دید كه به دور هم جمع شده و مشغول صحبت هستند. نزد آنها رفت و گفت: هركس بگوید در دستمال من چه چیزی هست یكی از زردآلو هائی را كه در آن گذاشته ام به وی خواهم داد. یكی از مردان فكری كرد و گفت: آقا ما مردمانی ساده هستیم و از غییب گوئی سررشته ای نداریم تا بدانیم داخل دستمال شما چیست و زردآلوئی جایزه بگیریم.\r\n"},{"id":152,"category_id":3,"category_code":"s3","source_id":72,"title":"ملا و مرد ديوانه ","content":" روزی ملا نصرالدین از كنار حوض مسجدی كه پر از آب بود میگذشت. مردی را دید كه در كنار حوض نشسته و قوطی گوگردی در دست دارد به زیر آب فرو برده و مشغول آتش كردن است. ملا نزدیكتر رفت و پرسید: برادر چه كار میكنی؟ مرد دیوانه سری جنباند و گفت: یك قران پولم در حوض افتاده و چون پایین حوض تاریك است و نمیتوانم آنرا بیبینم گوگرد میزنم تا روشن شود و پولم را پیدا كنم.\r\n ملا فكری كرد و لبخند تمسخر آمیزی زد و گفت: عجب آدم دیوانه استی, خوب تو هر چقدر گوگرد را در زیر آب بخواهی روشن كنی روشن نخواهد شد. دیوانه به تندی پرسید: خوب جناب با عقل شما میفرمائید چه كار باید بكنم تا زیر حوض روشن شود و بتوانم پولم را پیدا كنم. ملا گفت: هان.... تو باید گوگرد را خارج از آب روشن كنی و بعد ار آن به داخل آب فرو ببری تا بتوانی سكه ات را یابی.\r\n"},{"id":153,"category_id":3,"category_code":"s3","source_id":73,"title":"عزاداري جوجه ها و ملا","content":" ملا مرغ بزرگ و خوبی داشت كه چند جوجه بدنیا آورده بود. از قضا یك روز مرغ مرد و ملا پس از مردن وی چند تكه پارچه سیاه رنگ كوچك برداشته و میانش را سوراخ كرده و به گردن جوجه های مرغ انداخت. یكی از دوستانش كه آن صحنه را دیده بود، پرسید برای چه آن كار را كرده است.\r\n ملا گفت: دوست عزیز مادر این جوجه ها مرده است و آنها برای وی عزادار هستند.\r\n"},{"id":154,"category_id":3,"category_code":"s3","source_id":74,"title":"مهمان ملا","content":" روزی شخصی به خانه ملا آمد و مهمان وی شد. ملا برایش غذا آورد و آن مرد بعد از خوردن غذا گفت: در شهر ما رسم است كه پس از خوردن غذا مقداری هم میوه میخورند. ملا به تندی سرش را جنباند و گفت: برعكس در شهر ما این كار بسیار بد و ناپسند است."},{"id":155,"category_id":3,"category_code":"s3","source_id":75,"title":"تدبير ملا ","content":" شبی در فصل تابستان كه ملا با زنش روی بام خوابیده بودندش، دزدی ناشی به بام آمد.\r\n ملا ورود او را فهمیده و دانست كه خیال دارد در صحن خانه دستبردی بزند. تدبیری كرده بدون اینكه بفهماند از آمدن دزد آگاه شده با زنش صحبت كنان گفت: دیشب را نپرسیدی بعد از نصف شب من بدون صدا كردن تو با اینكه درب بام بسته بود چطور به صحن خانه رفتم.\r\n زن گفت: راستی فراموش كردم چطور رفتید؟ ملا گفت: خیلی آسان، این اسم اعظم را خوانده از بالای بام مهتاب را به دست گرفته به آسانی به صحن خانه رسیدم.\r\n دزد از یاد گرفتن این موضوع خیلی خرسند شد و خواست به تقلید از ملا از راه مهتاب به صحن خانه وارد شود ولی خواندن اسم اعظم با افتادن او میان خانه برابر بوده باعث شكستن سر و پایش گردید. ملا به زنش گفت: برخیز چراغ بیاور ببینم كی بود كه به خانه آمد. \r\nدزد گفت: شتاب لازم نیست مادام كه تو اسم اعظم میدانی و من هم به این حماقت هستم با پای شكسته در خانه تو مهمان بوده و تا چند روز دیگر هم از جای خود برنمی خیزم.\r\n"},{"id":156,"category_id":3,"category_code":"s3","source_id":76,"title":"ملا و گدا ","content":" روزی ملا در بالاخانه بود كه صدای در خانه بلند شد.\r\nملا از بالا پرسید:كیست؟كسی كه در می زد، گفت بی زحمت بیایید پایین در را باز كنید.ملا پایین آمد و در را باز كرد . چشمش به گدایی افتاد كه گفت: محض رضای خدا یك لقمه نان به من بده.\r\n ملا گفت: با من بیا بالا. مرد فقیر به دنبال ملا از پله ها بالا رفت، چون به بالاخانه رسیدند ملا گفت: خدا بدهد، چیزی ندارم. گدا گفت: خوب مرد حسابی تو كه نمی خواستی چیزی به من بدهی چرا همان پایین به من نگفتی و از این همه پله مرا بالا آوردی!؟ ملا گفت: تو كه چیزی می خواستی ، چرا از همان پایین نگفتی و مرا تا دم در كشاندی؟\r\n"},{"id":157,"category_id":3,"category_code":"s3","source_id":77,"title":"دزد در خانه ملا ","content":" یك شب دزدی به خانه ملا آمده بود و همه جا را می گشت كه چیزی پیدا كند و ببرد ناگهان ملا از آواز پای او بیدار شد و تا او را دید گفت: آنچه تو در شب تاریك میجوئی ما در روز روشن جسته ایم و نیافته ایم."},{"id":158,"category_id":3,"category_code":"s3","source_id":78,"title":"عمامه ملا ","content":" ملا عمامه بزرگی بر سر گذاشته بود. مرد بیسوادی به نزد وی رفته و كاغذی به او داد و تقاضا كرد آنرا برایش بخواند.\r\n ملا گفت خواندن نمیداند. مرد مزبور با تعجب به سرا پای وی نگریست و گفت: اگر خواندن بلد نیستی پس عمامه به این\r\nبزرگی را برای چه به سرت گذاشته ای؟\r\n ملا بلافاصله امامه را از سر خود برداشته و بر سر آن مرد نهاد و گفت: بفرما اگر امامه داشتن دلیل سواد دار بودن است و برای آدم سواد میاورد حالا كه تو آنرا بر سر داری كاغذ را بخوان.\r\n"},{"id":159,"category_id":3,"category_code":"s3","source_id":79,"title":"ملا وشكر كردن خدا ","content":" شبی ملا به حیاط رفت، دید دزدی در گوشه حیاط ایستاده. زنش را صدا زد و تیر و كمانش را خواست .\r\n زن آن را آورد و ملا تیری به جانب دزد رها كرد و گفت:دیگر تا صبح كاری ندارم\r\nچون صبح شد ملا به سراغ دزد آمد، دید دزد همان قبای خودش است كه به میخ آویزان بوده و تیر هم به قبا خورده و آن را سوراخ كرده است. پس به زنش گفت: شكر خدا كن كه خودم در میان قبا نبودم و گرنه من هم به جای دزد مرده بودم.\r\n"},{"id":160,"category_id":3,"category_code":"s3","source_id":80,"title":"خدایی ملا","content":" غلام سیاه پر طمعی روزی در پائین محراب مسجد كه اتفاقا ملا در آن مناجات میكرد ناگهان پرسید: خدایا هزار سال در نظر تو چقدر است؟\r\nملا گفت: ای بنده ی من حكم یك ثانیه را دارد. غلام باز هم پرسید: ده هزار دینار در نظرت چقدر است؟ ملا گفت: ای بنده ی من مانند یك دینار.\r\nغلام گفت: پس این یك دینار را برای من اعطا فرما. ملا جواب داد: یك ثانیه صبر كن.\r\n"},{"id":161,"category_id":3,"category_code":"s3","source_id":81,"title":"قرباني ملا ","content":"ملا پیراهنش را روی طناب بالای بام آویخته بود. اتفاقا باد سختی وزید و پیراهن را به میان حیاط انداخت. ملا به زنش گفت: بایستی گوسفندی قربانی كنیم. وقتی زنش علت این كار را پرسید ملا گفت : برای این كه من میان پیراهن نبودم و گرنه چیزی از من باقی نمی ماند."},{"id":162,"category_id":3,"category_code":"s3","source_id":82,"title":"درخت كاري ملا ","content":" ملا باغ كوچكی در كنار خانه اش داشت كه به هنگام بهار چندین درخت در آن میكاشت. اما وقتی هوا تاریك میشد درختها را از داخل زمین خارج كرده و به خانه اش میبرد و در گوشه اطاق میگذاشت.\r\nمردم از این كار عجیب ملا حیرت كرده بودند روزی به نزد وی رفته و علت را جویا شدند. ملا دستی به ریش خود كشیده و گفت: میدانید رفقا در این شهر مدتی است كه دزد زیاد شده و من برای آنكه آنها نتوانند درختهایی را كه كاشته ام بربایند آنها را شبها به اطاقم میبرم.\r\n"},{"id":163,"category_id":3,"category_code":"s3","source_id":83,"title":"ملا و اولاد مرد صد ساله ","content":" از ملا پرسیدند: ممكن است از از مرد صد ساله زنش حامله شود و بزاید؟ ملا جواب داد: اگر همسایه جوان و بیست ساله ای داشته باشد, بلی!"},{"id":164,"category_id":3,"category_code":"s3","source_id":84,"title":"ملا و قيمت حلوا ","content":" ملا با پسرش به دُكان حلوا فروشی رفته حلوائی خریده به پسر داد كه به خانه برد و خود مشغول دیدن سایر حلوا ها شد. پس از اطمینان از دور شدن پسر رو به حلوا فروش كرده گفت: اگر كسی از شما حلوا بخرد و پول نداشته باشد به او چه خواهید كرد؟\r\n حلوا فروش گفت: لگدی به او زده بیرونش میكنم. ملا گفت: بی معطلی به من لگدی بزنید. صاحب دكان لگدی به او زده خواست بیرون اش بكند. ملا گفت: اگر به این قیمت میدهید یك مقدار دیگر هم حلوا بردارم.\r\n"},{"id":165,"category_id":3,"category_code":"s3","source_id":85,"title":"پسر ملا ","content":" پسر ملا به چاه پر از آبی افتاده و فریاد میزد و کمک میخواست ملا به لب چاه رفت و به داخل آن نگریست و گفت: پسر جایی نرو تا بروم از ده بالا زینه ای آورده و تو را نجات بدهم."},{"id":166,"category_id":3,"category_code":"s3","source_id":86,"title":"وصيت ملا ","content":" ملا به دوستانش وصیت كرد كه پس از مرگ قبر مرا با سنگ و خشت نسازید. پرسیدند چرا؟ گفت میخواهم روز قیامت كه سر از قبر بر میدارم از این حیث در عذاب نبوده به راحتی بر خیزم!"},{"id":167,"category_id":3,"category_code":"s3","source_id":87,"title":"نامه براي ملا ","content":" ملا به شهر نزدیكی رفته و مدتی توقفش به طول انجامید. روزی نامه ای به خانواده اش نوشته هر چه تجسس كرد كسی را برای بردن آن نیافت پس خودش آنرا برداشته به شهر و خانه خود رفت و درب را زد.\r\n زن و اولادش بیرون آمده از آمدنش شادی كردند. ملا به آنها گفت: نه من نیامده ام كه اینجا بمانم بلكه برای رساندن این نامه آمده ام. سپس نامه را داده و برگشت. هر چه اصرار كردند كه اقلا بمان خستگی بگیر، قبول نكرده راه افتاد.\r\n"},{"id":168,"category_id":3,"category_code":"s3","source_id":88,"title":"ملا تازه وارد ","content":" ملا وارد شهری شده و در كوچه و بازار گردش میكرد و به اینطرف و آنطرف مینگریست كه مردی جلو آمده و پرسید: آقا ممكن است بگویی امروز چند شنبه است؟ ملا نگاهی به قیافه آن مرد انداخت و گفت: والله نمیدانم چون من تازه وارد این شهر شده ام و هنوز هیچ جا را بلد نیستم."},{"id":169,"category_id":3,"category_code":"s3","source_id":89,"title":"ملا و گداي سمج ","content":" گدای سمجی هر روز به در خانه ملا می آمد و تقاضای كمك میكرد. بار اول و دوم و سوم ملا آنچه را داشت به وی داد اما گدا به این زودی ها دست از سرش بر نمیداشت ملا كه دیگر از دست سماجت وی به تنگ آمده بود نقشه ای كشید و یكروز وقتی گدا در خانه را به صدا در آورد.\r\nملا پرسید: كی است؟\r\nگدا از پشت در گفت : مهمان خدا\r\nملا به دم در رفته و آنر گشود و دست گدا را گرفته گفت: بیا تا كمك نمایم. گدا خوشحال شد و به دنبال ملا به راه افتاد. ملا پس از گذشتن چند كوچه وارد مسجد شد و به مرد گدا گفت: دوست عزیز تو اشتباها به خانه من میامدی چون خانه خدا اینجاست و لاجرم تو كه مهمان خدا هستی باید به این مكان مراجعه كنی.\r\n"},{"id":170,"category_id":3,"category_code":"s3","source_id":90,"title":"جنگ رفتن ملا ","content":" در میان اهالی دو ده جنگ در گرفته بود و آنها بر سر یكدیگر ریخته و از كشته پشته میساختند.\r\n عده ای از مردم جمع شده و چند نفر از نیرومند ترین پهلوانان شهر را جمع كرده و برای كمك به اهالی یكی از دهكده ها به جنگ فرستاندند و ملا هم در میان آنها بود و یك شمشیر و یك سپر هم به وی داداه بودند. ملا و سایرین به جنگ رفتند. پس از چند روز ملا با سر شكسته و بدن زخمی باز گشت.\r\n پرسیدند برای چه از خودت دفاع نكردی و گذاشتی آنها تو را زخمی كنند؟ ملا گفت: آخر آدمهای حسابی خود تان اگر جای من بودید و در دستهایتان یك شمشیر و یك سپر بود با كجای خود دفاع میكردید.\r\n"},{"id":171,"category_id":3,"category_code":"s3","source_id":91,"title":"راهنمائي ملا ","content":" روزی شخصی تفنگچه ای پیدا كرد و آنرا نزد ملا برد و از او پرسید: ملا جان بگو این چی است؟\r\n ملا نگاهی به تفنگچه انداخت و گفت: آن چپق (چلم) فرنگی است\r\nمردی كه تفنگچه را پیدا كرده بود خوشحال شد و آنرا به دهان خود گذارده و خواست بكشد. اما ناگهان گلوله ای رها شد و مرد بیچاره نقش زمین شد. ملا نگاهی به جسد بی جان او انداخت و گفت: عجب تمباكوی خوبی داخل این چپق بود، تا یك پك كشید نشه شد و روی زمین افتاد.\r\n"},{"id":172,"category_id":3,"category_code":"s3","source_id":92,"title":"ملا و آش سرد شده ","content":" از ملا پرسیدند در زبان عربی به آش سرد شده چی میگویند؟\r\n ملا چون نمیدانست پس از لحظه ای گفت: عرب ها هیچ وقت نمیگذارند آش سرد شود!\r\n"},{"id":173,"category_id":3,"category_code":"s3","source_id":93,"title":"سيلي خوردن ملا ","content":" یكروز ملا از كوچه ای میگذشت كه مردی جلو آمده و سیلی سختی بر گوش وی نواخت.\r\n ملا توقف كرد و با چهره حیرت زده به آن مرد نگریست. مرد مزبور پس از آن كه خوب به چهره ملا نگریست دانست كه اشتباه كرده و او را به جای شخص دیگری سیلی زده، این بود كه شروع به عذر خواهی كرد. اما ملا سیلی خورده بود قانع نشد. و یخه مرد عابر را گرفته و او را نزد قاضی برد و تمام ماجرا را به قاضی بازگو كرد. قاضی پس از كمی فكر رو به طرف ملا كرده و گفت كه او هم یك سیلی بر گوش آن مرد بزند.\r\nولی ملا به این كار راضی نشد و قاضی به مرد مزبور گفت یك سكه طلا به جای سیلی ای كه به ملا زده به وی بدهد. مرد به ناچار تسلیم شده گفت پول ندارد، به خانه میرود و یك سكه طلا برای ملا میاورد.\r\nمدتی از رفتن مرد مزبور گذشت و اثری از او پیدا نشد. ملا كه دیگر از انتظار كشیدن خسته شده بود برخاست و به طرف قاضی رفته و سیلی سختی بر گوش وی نواخت و سپس گفت: جناب قاضی چون من خیلی كار دارم باید هر چه زودتر بروم و خواهش میكنم وقتی آن شخص پول را آورد شما بجای این سیلی ای كه زدم آن را بگیرید.\r\n"},{"id":174,"category_id":3,"category_code":"s3","source_id":94,"title":"ملا و مزد حمالي","content":" روزی ملا باری به دوش حمالی گذاشت كه همراهش به منزل بیاورد. دربین راه حمال گم شد و هر چه گشت او را نیافت تا ده روز كارش جستجوی او بود بالاخره روز دهم با جمعی از دوستانش از كوچه می گذشتند كه چشمش به آن حمال افتاد كه بار دیگری به دوش دارد به دوستانش گفت: این همان حمال است كه من در تعقیبش هستم .\r\n ولی بدون این كه به حمال حرفی بزند، از آن جا دور شد . دوستانش پرسیدند: چرا از حمال باز خواست نكردی و بارت را مطالبه ننمودی ؟ گفت: فكر كردم اگر اجرت این ده روز حمالی را از من بخواهد چه كنم؟\r\n"},{"id":175,"category_id":3,"category_code":"s3","source_id":95,"title":"ملا و دود كباب ","content":" مرد فقیری از كنار دكان كباب فروشی میگذشت. مرد كباب فروش گوشت ها را در سیخها كرده و به روی آتش نهاده باد میزند و بوی خوش گوشت سرخ شده در فضا پراكنده شده بود.\r\n بیچاره مرد فقیر چون گرسنه بود و پولی هم نداشت تا از كباب بخورد تكه نان خشكی را كه در توبره داشت خارج كرده و بر روی دود كباب گرفته به دهان گذاشت.\r\n او به همین ترتیب چند تكه نان خشك خورد و سپس براه افتاد تا از آنجا برود ولی مرد كباب فروش به سرعت از دكان خارج شده دست وی را گرفت و گفت: كجا میروی پول دود كباب را كه خورده ای بده!\r\nاز قضا ملا از آنجا میگذشت جریان را دید و متوجه شد كه مرد فقیر التماس و زاری میكند و تقاضا مینماید او را رها كنند.\r\n ولی مرد كباب فروش میخواست پول دودی را كه وی خورده است بگیرد. ملا دلش برای مرد فقیر سوخت و جلو رفته به كباب فروش گفت: این مرد را آزاد كن تا برود من پول دود كبابی را كه او خورده است میدهم.\r\n كباب فروش قبول كرد و مرد فقیر را رها كرد. ملا پس از رفتن فقیر چند سكه از جیبش خارج كرده و در حال كه آنها را یكی پس از دیگری به روی زمین میانداخت به مرد كباب فروش گفت: بیا این هم صدای پول دودی كه آن مرد خورده، بشمار و تحویل بگیر.\r\nمرد كباب فروش با حیرت به ملا نگریست و گفت: این چه طرز پول دادن است مرد خدا؟ ملا همان طور كه پول ها را بر زمین میانداخت تا صدایی از آنها بلند شود گفت: خوب جان من كسی كه دود كباب و بوی آنرا بفروشد و بخواهد برای آن پول بگیرد باید به جای پول صدای آنرا تحویل بگیرد.\r\n"},{"id":176,"category_id":3,"category_code":"s3","source_id":96,"title":"ملا و پشك ","content":"ملا پشكی داشت بسیار زیبا و خوش نقش و نگار, روزی متوجه شد كه بدن پشك بسیار چرك و كثیف شده است. تصمیم گرفت آنرا بشوید.\r\n او پشك را برداشته و به كنار جوی آب رفت و مشغول شستن بدن پشك شد. مردی از انجا میگذشت وقتی آن صحنه را دید گفت: ملا برای چه پشك را میشویی؟ ملا گفت: كثیف است میخواهم پاك بشود.\r\nرهگذر گفت: ولی ممكن است پشك ناراحت بشود و بمیرد. او این را گفت و ازاینجا رفت. اما وقتی برگشت متوجه شد كه پشك مرده و در كنار جوی آب افتاده و ملا هم نشسته به آن مینگرد. مرد مزبور گفت: نگفتم اگر پشك را بشویی خواهد مرد.\r\nملا گفت: ولی او از شستن نمرد. مرد پرسید: پس چطور شد كه جان سپرد؟ ملا گفت: من او را شستم و برای اینكه آب بدنش از بین برود تابش دادم آنوقت بود كه مرد.\r\n"},{"id":177,"category_id":3,"category_code":"s3","source_id":97,"title":"انگور ","content":" روزی ملانصرالدین  سبدی انگور روی خرش گذاشته و به شهری رفت.\r\nجوانهای محل جلوی او را گرفته و گفتند : ملا به ما انگور نمیدهی؟وقتی ملا جمعیت را دید فکر کرد اگر به هر کدام یک خوشه انگور بدهد دیگر چیزی در سبد باقی نمی ماند تا به خانه ببرد پس یک خوشه بیرون آورده و به هر نفر یک حبه انگور داد و گفت : چون غرض چشیدن است . مزه یک حبه با یک خوشه تفاوتی ندارد!\r\n"},{"id":178,"category_id":3,"category_code":"s3","source_id":98,"title":"آشنایی ","content":" عده ای در بیابان نشسته بودند و غذا می‌خوردند. ملانصرالدین که از آنجامی‌گذشت، بدون تعارف کنارشان نشست و شروع کرد به خوردن.\r\nیکی پرسید: جنابعالی با کی آشنایید؟\r\nنصرالدین غذا را نشان داد و گفت: با ایشان!\r\n"},{"id":179,"category_id":3,"category_code":"s3","source_id":99,"title":"فرق دو گره ","content":" روزی ملا، کیسه گندمی را آرد کرده بود و داشت به خانه اش می برد. در راه با خدا راز و نیاز می کرد که خداوند گره از مشکلاتش باز کند. ناگهان گره کیسه آرد باز شد و تمام آردها به زمین ریخت. ملا با ناراحتی سرش را به آسمان بلند کرد و گفت: خدایا بعد از این همه سال خدایی کردن فرق دو تا گره را نمی دانی و من را این طور ذلیل و بیچاره می کنی؟"},{"id":180,"category_id":3,"category_code":"s3","source_id":100,"title":"کار بی زحمت ","content":" روزی ملانصرالدین سوار خرش بود و داشت رد می شد که یک دفعه خرش رم کرد و او را به زمین زد. بچه های کوچه وقتی ملا را با این وضع دیدند حسابی او را دست انداختند\r\nملانصرالدین به خنده های بچه ها اعتنایی نکرد. بلند شد و گرد و خاک لباسش را تکاند و به طرف خانه ای رفت و در زد و گفت: چه خوب شد خرم مرا دم همان خانه ای که کار داشتم زمین زد و مرا از زحمت پیاده شدن خلاص کرد.\r\n"},{"id":181,"category_id":3,"category_code":"s3","source_id":101,"title":"ماهی یونس ","content":" ماهیگیران کنار رودخانه ای مشغول ماهیگیری بودند. ملا ایستاده بود و آنها را نگاه می کرد که یک دفعه پایش لیز خورد و افتاد توی آب.\r\nیکی از ماهیگیران پرسید: حضرت عالی را بجا نمی آورم؟ ملانصرالدین گفت: فرض کنید ماهی حضرت یونس!\r\n"},{"id":182,"category_id":3,"category_code":"s3","source_id":102,"title":"عمامه ملا ","content":" روزی ملانصرالدین داشت از چاه آب می کشید و به خرش می داد. یکدفعه پوزه خر به کله ملا خورد و عمامه اش افتاد توی آب. ملانصرالدین سریع افسار خر را باز کرد و انداخت توی چاه. رفیقی او را دید و گفت: ملا، این چه کاری بود که کردی؟ ملا گفت: برای اینکه هر کسی رفت افسار الاغ را بیاورد عمامه من را نیز با خودش بالا بیاورد."},{"id":183,"category_id":3,"category_code":"s3","source_id":103,"title":"علت دویدن ","content":" روزی باران شدیدی می بارید. ملا پنجره خانه را باز کرده بود و داشت بیرون را نگاه می کرد. در همین حین همسایه اش را دید که داشت به سرعت از کوچه می گذشت\r\nملا داد زد: آهای فلانی! کجا با این عجله؟\r\n همسایه جواب داد: مگر نمی بینی چه بارانی دارد می بارد؟\r\nملا گفت: مردک خجالت نمی کشی از رحمت الهی فرار می کنی؟\r\nهمسایه خجالت کشید و آرام آرام راه خانه را در پیش گرفت. چند روزی گذشت و بر حسب اتفاق دوباره باران شروع به باریدن کرد و این دفعه همسایه ملا پنجره را باز کرده بود و داشت بیرون را تماشا می کرد که \r\nیکدفعه چشمش به ملا افتاد که قبایش را روی سر کشیده است و دارد به سمت خانه می دود.\r\nفریاد زد: آهای ملا! مگر حرفت یادت رفته؟ \r\nتو چرا از رحمت خداوند فرار می کنی؟ ملانصرالدین گفت: مرد حسابی، من دارم می دوم که کمتر نعمت خدا را زیر پایم لگد کنم.\r\n"},{"id":184,"category_id":3,"category_code":"s3","source_id":104,"title":"یاد بچگی ","content":" در یکی از روزها بچه ها توی کوچه مشغول بازی بودند. ملانصرالدین پشت دیواری ایستاده بود و یواشکی بازی آنها را نگاه می کرد.\r\n از قضا یکی از بچه ها ملا را زیر نظر گرفته بود و از پشت سر عمامه ملا را از سر او \r\nبرداشت و برای دوست دیگرش انداخت و به همین ترتیب عمامه ملا دست به دست شد و بچه ها با آن بازی کردند..\r\nملا هر چه دنبال بچه ها کرد نتوانست عمامه اش را پس بگیرد. عاقبت از خیر پس گرفتن عمامه اش گذشت و راه خانه را در پیش گرفت در بین راه عده ای ملا را دیدند و گفتند: ملا عمامه ات کو؟\r\nملانصرالدین گفت: عمامه من یاد بچگی اش افتاده، رفته پیش بچه ها بازی کند.\r\n"},{"id":185,"category_id":3,"category_code":"s3","source_id":105,"title":"ملای پخمه ","content":" ملانصرالدین تبری داشت که بسیار برایش با ارزش بود و هر شب آن را در تنور پنهان می کرد و در تنور را هم می گذاشت.\r\nعیالش گفت: ملا تبر را چرا در تنور می گذاری؟\r\nملا جواب داد: از دست گربه قایم می کنم.\r\nزن گفت: گربه تبر را می خواهد چه کند؟\r\nملانصرالدین گفت: عجب زن احمقی هستی! گربه تکه گوشتی را که قیمتی ندارد می برد، اما تبری را که ده دینار خریده ام رها خواهد کرد؟\r\n"},{"id":186,"category_id":3,"category_code":"s3","source_id":106,"title":"تنبیه قبل از اشتباه ","content":" ملا کوزه اش را دست دخترش داد و سیلی محکمی هم به صورت او زده و گفت: به سر چشمه برو آب بیاور. مبادا آن را بشکنی. دخترک گریه کنان از پیش او رفت. پرسیدند:\r\nچرا کودک بیچاره را اینطور بی جهت زدی؟\r\n گفت: او را زدم که کوزه را نشکند، زیرا اگر بعد از شکستن او را تنبیه نمایم فایده ندارد و آن کوزه برای من کوزه نمی شود.\r\n"},{"id":187,"category_id":3,"category_code":"s3","source_id":107,"title":"ماجرای ملانصرالدین و دیگ بچه زا !! ","content":"روزی ملا به در خانه ی همسایه رفت و از او درخواست یک دیگ را نمود. همسایه ظرف را داد.\r\nبعد از چند روز بعد ملا دیگ را به همراه یک دیگچه آورد.\r\nهمسایه با تعجب پرسید که دیگچه دیگر چیست؟\r\nملا پاسخ داد که دیگ یک دیگچه زایید و همسایه با خوشحالی پذیرفت...\r\nچند روز بعد دوباره ملا دیگ را درخواست کرد همسایه به امید زاییدن دیگ، دیگ را به او داد و مدتی گذشت و ملا دیگ را نیاورد.\r\nهمسایه برای دریافت دیگ خود را به در خانه ی ملا رسانید و دیگ خود را درخواست کرد.\r\nاما ملا با گریه پاسخ داد که دیگ مُرد.\r\nهمسایه با تعجب پرسید مگر دیگ می میرد؟\r\nملا گفت: این بار هم مانند بار قبل دیگ در حال زاییدن بود که سر زا مرد!!!\r\n"},{"id":188,"category_id":3,"category_code":"s3","source_id":108,"title":"دل درد زن ملا ","content":" زن ملا دل درد شدیدی گرفت و ملا برای آوردن طبیب بیرون رفت. چون به كوچه رسید زنش از پنجره گفت : دلم آرام گرفت، طبیب لازم نیست.\r\nملا به حرف او گوش نداد و به خانه طبیب رفت و او را از اندرون بیرون كشید و گفت: زن من دل درد شدیدی گرفته بود ومن برای آوردن شما می آمدم كه از پنجره صدا كرد دلم آرام گرفته و به طبیب احتیاجی نیست. من هم آمدم كه به شما اطلاع دهم كه به آمدن شما نیازی نیست!\r\n"},{"id":189,"category_id":3,"category_code":"s3","source_id":109,"title":"قضاوت ملا ","content":" دو نفر به شراكت شتری خریدند. یكی دو ثلث قیمت و دیگری ثلث قیمت آن را پرداخته و قرار گذاشتند كه منفعت را هم به تناسب سرمایه قسمت كنند.\r\nاتفاقا\" شتر با بار در صحرا گرفتار سیل شد و از بین رفت. در نتیجه بین شركا نزاع در گرفت و صاحب دو ثلث كه مرد ثروتمندی بود از شریكش دست بردار نبود و از وی خسارت می طلبید. عاقبت كارشان به محضر قاضی كشیده شد و هر دو نفر نزد ملا كه بر مسند قضاوت نشسته بود رفتند.\r\nملا پس از شنیدن ادعای طرفین چون وضعیت را حس كرد چنین رای داد : چون دو سهم صاحب دو ثلث سنگینی كرده و باعث غرق شتر در سیل گشته است، او بایستی سهم طرف دیگر را بپردازد.\r\n"},{"id":190,"category_id":3,"category_code":"s3","source_id":110,"title":"پایین آوردن بنا ","content":" گویند بنایی دیواری را می ساخت و در بالای آن گیر کرده بود و مردم برای پایین آوردن او متحیر بودند که پیش ملانصر الدین رفتند و از اوکمک خواستند.\r\n ملا هم دستور داد که یک طناب بیاورند و به بنا ببندند.طناب را آوردند و پرتاب نمودند و بنا آنرا به خود بست. سپس گفت حال طناب را بکشید بنای بدبخت از آنجا پرت شد و در دم جان سپرد.\r\nملانصرالدین در حالی که داشت فرار می کرد می گفت عجبا من هزاران نفر را با همین روش از چاه نجات دادم عجیب که ایندفعه راه حل ما کار ساز نبود!\r\n"},{"id":191,"category_id":3,"category_code":"s3","source_id":111,"title":"چشم درد ","content":" مردی نزد ملا رفته و گفت چشمم درد میكند چه كنم تا خوب شود. ملا فكری كرد و گفت: چندی قبل دندان من درد گرفت آنرا كندم و به دور انداختم!"},{"id":192,"category_id":3,"category_code":"s3","source_id":112,"title":"كتاب ملا ","content":" ملا را به مجلس جشنی دعوت كرده بودند ولی وقتی داخل خانه شد و به در اطاقی كه مهمانان در آنجا بودند نگریست متوجه شد تعداد بسیار زیادی كفش در كنار دراتاق چیده شده است.\r\n ملا هم اول خواست كفشهای خود را خارج كرده سپس وارد اطاق بشود اما با خودش اندیشید اگر كفش های خود را كنار كفشهای سایر مهمانان بگذارد چون تعداد آنها خیلی زیاد است ممكن است كفشهایش گم بشود،پس آنها را از پای خود خارج ساخته و در دستمالی پیچید و در جیب خود گذاشته\r\nوارد اطاق شد. \r\nدر میان جشن مردی در كنارش نشسته بود و متوجه برآمدگی جیب وی شده و گفت: مثل اینكه كتاب ذیقیمتی را در جیب خود نهاده ای؟\r\n ملا سرش را جنباند و گفت: همینطور است. \r\nمرد مزبور پرسید: در باره چه موضوعی است. ملا فكری كرد و اظهار داشت: در باره فلسفه. مرد مذبور پرسید: حتما آنرا از كتابفروش سر كوچه خریده ای؟ ملا بلافاصله جواب داد: خیر آنرا از كفش دوز سر كوچه خریده ام.\r\n"},{"id":193,"category_id":3,"category_code":"s3","source_id":113,"title":"ملا و حاكم ","content":" یكروز ملا گوسفندی برای حاكم شهر هدیه برد. حاكم از این كار او خوشش آمد و یكی از غلامانش را صدا زد و گفت به جای این گوسفند یك خر به این مرد بدهید.\r\n ملا به تندی گفت: اختیار دارید قربان شما خودتان بیشتر از صد خر برای ما ارزش دارید!\r\n"},{"id":194,"category_id":3,"category_code":"s3","source_id":114,"title":"تنبيه ملا ","content":" ملانصرالدین را نزد پادشاه بردند تا تنبیه شود...\r\nپادشاه گفت: او را دو هزار ضربه شلاق بزنید.\r\nملا گفت:تو یا تا به حال شلاق نخورده ای یا حساب بلد نیستی...\r\n"},{"id":195,"category_id":3,"category_code":"s3","source_id":115,"title":"كلاغ و صابون ملا ","content":" روزی زن ملا رخت می شست كه ناگهان كلاغی صابون را برداشت و بالای درختی برد. \r\nملا را صدا زد و گفت:بیا كلاغ صابون را برد. ملا با بی اعتنایی گفت: می بینی كه لباس بچه كلاغ از ما سیاه تر است، پس احتیاج او به صابون بیشتر است!!\r\n"},{"id":196,"category_id":3,"category_code":"s3","source_id":116,"title":"نقل مكان ملا ","content":" شبی ملا در خانه خود خفته بود كه دزدی كم روزی وارد شد ، مختصر اثاثیه او را جمع كرد و به دوش كشید و بیرون رفت. ملا نیز بر خاست و رختخواب را بر داشت و دنبال دزد به راه افتاد تا هر دو وارد منزل دزد شدند. دزد او را دید و با تشدد گفت : این جا چه می كنی ؟ \r\nملا گفت: هیچ، بنده تغییر منزل داده ام ، اجرت حمالی شما نیز حاضر است.\r\n"},{"id":197,"category_id":3,"category_code":"s3","source_id":117,"title":"ملا وسكه طلا","content":"  ملا سکه طلایی در دست داشت و مشغول بازی کردن با سکه بود، که شخصی که شنیده بود ملا مرد ابلهی است پیش آمده و گفت : اگر این سکه را به من بدهی در مقابل هشت سکه زرد مسی به تو می دهم. \r\nملا گفت : به شرطی اینکار را میکنم که تو سه بار مثل خر عرعر کنی.\r\nآن شخص طماع، سه بار عرعر کرد. \r\nملا گفت: عجب خری هستی ، تو با این خریتت فرق طلا و سکه زرد را فهمیدی اما من نفهمیده ام که طلا را نباید با پول مسی عوض کنم ؟!!\r\n"},{"id":198,"category_id":3,"category_code":"s3","source_id":118,"title":"ملا و ازدواج ","content":" ملا میخواست زن بگیرد. همسایه ها از زنی بسیار تعریف کردند که ملا ندیده عاشق شد. \r\nمخصوصا از چشمهای شهلایش بسیار وصف کردند. عاقبت ملا تسلیم شده او را عقد کرد.\r\nدر شب عروسی خربزه ای خریده به خانه آورد. زن که لوچ بود، به او اعتراض نمود که چرا اسراف کرده و دو خربزه خریدی؟\r\n ملا فهمید زن لوچ است ولی چاره ای نداشت.\r\nدر سر سفره به او گفت: این شخص که پهلوی شما نشسته کیست؟ ملا گفت هرچه را دوتا می بینی عیب ندارد، خواهش می کنم من یکی را دو تا نبین!\r\n"},{"id":199,"category_id":3,"category_code":"s3","source_id":119,"title":"لحاف ملا ","content":" شبی از شب های سرد زمستان ملا خوابیده بود كه ناگاه سر و صدای زیادی از كوچه به گوشش رسید.\r\n ملا برای این كه ببیند چه خبر است لحافش را به دور خود پیچید و به كوچه رفت . \r\nاتفاقا\" رندی دست انداخت و لحاف ملا را از دوش او بر داشت و فرار كرد و در همین بین غائله دعوا نیز خوابید. ملا كه چنین دید، بدون لحاف به خانه برگشت. زنش پرسید: این سر و صدا برای چه بود و مردم چرا دعوا می كردند؟\r\n ملا گفت : چیزی نبود تمام دعوا بر سر لحاف من بود!\r\n"},{"id":200,"category_id":3,"category_code":"s3","source_id":120,"title":"ملا و معما ","content":" روزی شخصی تخم مرغی در دست خود پنهان كرد و از ملا پرسید: اگر گفتی در دست من چیست آن را به خودت می دهم تا با آن خاگینه درست كنی و بخوری.\r\n ملا گفت: قدری راهنمایی كن. آن شخص گفت: از مشخصات آن این است كه اطرافش سفید و داخل آن سفیدی ، زرد رنگ است.\r\n ملا پس از كمی فكر كردن گفت: فهمیدم، شلغمی است كه درون آن را خالی كرده و در آن هویج كار گذاشته اند!\r\n"},{"id":201,"category_id":3,"category_code":"s3","source_id":121,"title":"مريض شدن ملا ","content":" وقتی ملا مریض شد جمعی از اقوامش به دیدن او آمدند، نشستند و خیال رفتن نداشتند.\r\n ملا كه به تنگ آمده بود برخاست و گفت: خداوند مریض شما را شفا داد، برخیزید و به خانه بروید.\r\n"},{"id":202,"category_id":3,"category_code":"s3","source_id":122,"title":"کیسه زر ","content":" گویند روزی ملانصرالدین در کوچه ای می رفت که مردی کیسه زرش را از وی ربود.\r\n ملا شروع کرد به داد و هوار که آی مردم بردند ...کیسه ام را بردند...\r\nجمعی دور ملا را گرفتند و از آن میان یکی گفت: دیدی چه کسی کیسه ات را ربود؟\r\n ملا گفت: آری. مرد گفت : بیا به محکمه برویم و به قاضی شکایت کن\r\nخلاصه، ملانصرالدین و مردم به سوی محکمه حرکت کردند. وقتی رسیدند. قاضی آمد و گفت: سلام ملا؟ چه خبر؟ چه شده؟ ملا گفت : جناب قاضی... در همین حین مرد دیگری از در وارد شد و نشست. ملا به مرد نگاه کرد و حرفش را قطع کرد. قاضی با تعجب گفت: حرفت را بزن ملا. این مرد منشی محکمه و داروغه شهر است. ملا لبخندی زد و گفت: بنابراین من نه وقت شما را میگیرم نه جان خود را! ملا این را گفت و بیرون آمد. مردم متعجب به دنبالش شتافتند. مردی گفت: ملا چرا چنین کردی؟ چرا شکایتت را به قاضی نبردی؟\r\nملا گفت: هنوز قاضی را ندیده ام اما کیسه ام را باز میستانم...\r\nروز بعد مردم دیدند که ملانصرالدین در بازار فریاد می زند: آی مردم... کیسه ام... کیسه ام را یافتم...\r\nدوباره جماعتی دور ملا حلقه زدند. مردی گفت :‌ چطور کیسه ات را یافتی؟ چگونه است که کیسه ات بی حکم قاضی به تو بازگشت؟\r\nملا نصرالدین خنده ای کرد و گفت: دیروز بهتر دیدم در شهری که داروغه دزد باشد و قاضی رفیق دزد، شکایتم را به یک قاضی عادل برم. به خانه رفتم و نماز خواندم و کیسه ام را از خدا خواستم. امروز که در راه می رفتم دیدم داروغه کنار بیایان از اسب افتاده و گردنش شکسته است.\r\n کیسه زر من همچنان به کمرش بود. من نیز کیسه ام را برداشتم و آمدم.\r\n"},{"id":203,"category_id":3,"category_code":"s3","source_id":123,"title":"سركه ي هفت ساله و ملا ","content":"شخصی نزد ملا آمد و پرسید : می گویند شما سركه هفت ساله دارید آیا راست است؟\r\nملا جواب داد بله ، آن شخص گفت: خواهش می كنم یك كاسه به من بدهید.ملا گفت: عجب، اگر می خواستم آن را به هر كس بدهم كه یك ماه هم نمی ماند و هفت ساله نمی شد!\r\n"},{"id":204,"category_id":3,"category_code":"s3","source_id":124,"title":"ملا و ماهی ","content":" پدر ملا ماهی بریان شده به خانه آورد ، ملا نبود.\r\n مادرش گفت: خوب است قبل از آمدن ملا ماهی را بخوریم. که اگر او باشد، نمیگذارد به راحتی از گلویمان پایین رود.\r\n در این بین ملا در زد. مادرش دو ماهی بزرگ را زیر تخت پنهان کرده کوچکتر را در میان گذاشت، ملا از شکاف در نگاه می کرد، چون وارد شد و نشست، پدرش از او پرسید: پدر جان حکایت یونس را میدانی؟ ملا گفت از این ماهی می پرسیم، بعد سر را جلو برده ، گوش به دهن ماهی بنهاده گفت : این ماهی میگوید در آن زمان من کوچک بودم و این مطلب را از دو ماهی بزرگتر که زیر تخت هستند بپرسید!\r\n"},{"id":205,"category_id":3,"category_code":"s3","source_id":125,"title":"دعوت ","content":" ملا در مراسم تدفین سومین همسر یکی از دوستانش حضور یافت. وقتی به خانه برگشت سخت متأثر و اندوهگین  بود.\r\n زنش علت تأثر را پرسید. ملا گفت : پرا متأثر نباشم زیرا دوستم تاکنون سه مرتبه مرا در چنین مراسمی دعوت کرده است و من هنوز نتوانسته ام یک بار از او چنین دعوتی به عمل بیاورم.\r\n"},{"id":206,"category_id":3,"category_code":"s3","source_id":126,"title":"بالاتر از صدای رعد و برق","content":"یکی ازملا پرسید : چگونه دیشب صدای مهیب رعد و برق را نشنیدی؟\r\n ملا گفت : برای آن که داشتم با مادرزنم صحبت می کردم.\r\n"},{"id":207,"category_id":3,"category_code":"s3","source_id":127,"title":"حاضر جوابي ملا ","content":" روزی ملا به میدان مال فروشان رفته بود تا خر بخرد .جمع زیادی از دهاتی ها آن جا بودند و بازار خر فروشی رواج داشت. در این بین مردی كه ادعای نكته سنجی می كرد با خری كه بار میوه داشت از آن جا می گذشت خواست كمی سر به سر ملا بگذارد پس گفت: در این میدان به جز دهاتی و خر چیز دیگری پیدا نمی شود. ملا پرسید: شما دهاتی هستید؟ مرد گفت: خیر . \r\nملا گفت: پس معلوم شد كه چه هستید!\r\n"},{"id":208,"category_id":3,"category_code":"s3","source_id":128,"title":"زن زشت ملا ","content":" همسایه های ملا او گول زده و زن زشتی را به او تحمیل نمودن. پس از عروسی وقتی ملا خواست از خانه بیرون رود. آن زن گفت: خوب بود به من می گفتی كه هر یك از نزدیكان و دوستانت را چه قسم احترام بگزارم و دوست داشته باشم. ملا گفت: سعی كن از من یكی بدت بیاید، باقی را خود دانی هر كه را می خواهی دوست داشته باشی مهم نیست!"},{"id":209,"category_id":3,"category_code":"s3","source_id":129,"title":"بیتالخلآ ","content":"ملانصرالدین شب مهمان کسی بود . وقت استراحت کردن صاحب خانه میگوید . بیتالخلآ رفتی ؟ نصرالدین میگوید : نه قربانش شوم بسیار آرزویش را دارم."},{"id":210,"category_id":3,"category_code":"s3","source_id":130,"title":"باانصافی ملا ","content":" ملا مقداری چغندر و هویج و شلغم و ترب و سبزیجات مختلف دیگر خرید و در خورجینی ریخته و آن را به دوش انداخت. بعد سوار خر شد و به طرف خانه روان شد\r\nیکی از دوستانش که آن حال را دید پرسید: ملا جان چرا خورجین را به ترک خر نمی اندازی؟\r\nملا جواب داد: دوست عزیز آخر من مرد منصفی هستم و خدا را خوش نمی آید که هم خودم سوار خر باشم و هم خورجین را روی حیوان بیندازم!\r\n"},{"id":211,"category_id":3,"category_code":"s3","source_id":131,"title":"بی خوابی ","content":" شبی ملا بی خوابی به سرش زده بود، به همین جهت از خانه خارج شد و بی هدف در کوچه ها می گشت.\r\nیکی از دوستانش ملا را دید و از او پرسید: نیمه شب در کوچه ها چرا پرسه می زنی؟\r\nملا گفت: خوابم پریده، دنبالش می گردم شاید پیدایش کنم!\r\n"},{"id":212,"category_id":3,"category_code":"s3","source_id":132,"title":"پیری ","content":"یک روز از ملا پرسیدند که چرا اینقدر پیر شده است؟ ملا با تعجب گفت: که اشتباه می کنید زور من با جوانیم اندکی فرق نکرده است.\r\nچونکه آن زمان در گوشه حیات خانه ما یک گلدان سنگی بود که نمی توانستم آنرا بلند کنم اکنون هم که پیر شده ام نمی توانم.\r\nبه همین جهت زور بازویم هرگز کاهش نیافته است!\r\n"},{"id":213,"category_id":3,"category_code":"s3","source_id":133,"title":"گرسنگی ","content":" روزی ملا از دهی می گذشت گرسنه اش بود به روستائیان گفت: به من غذا بدهید و الا همان بلایی که بر سر ده قبلی آورده ام به سر شما هم می آورم!\r\nروستائیان ترسیدند و او را غذا دادند، ملا پس از آنکه سیر شد و عازم رفتن گردید یکی از روستائیان از او پرسید: به ما بگو با روستای قبلی چه معامله ای کردی؟\r\nملا خندید و گفت: هیچ غذایم ندادند، رهایشان کردم و به سراغ ده شما آمدم!\r\n"},{"id":214,"category_id":3,"category_code":"s3","source_id":134,"title":"ستاره شناس ","content":" روزی ملا از همسایه اش که مردی دانشمند بود و ستاره شناسی میکرد پرسید فلانی را می شناسی؟\r\nمرد گفت: نه!\r\nملا گفت: تو که همسایه ات را نمی شناسی چطور می خواهی ستارگان را بشناسی؟!\r\n"},{"id":215,"category_id":3,"category_code":"s3","source_id":135,"title":"درد ","content":" کسی نزد ملا رفت و به او گفت: موی سرم درد می کند دارویی بده تا خوب شوم.\r\nملا از او پرسید: امروز چه خوردی؟ مرد گفت: نان و یخ!\r\nملا گفت: برو بمیر که نه غذایت به آدمیزاد می ماند نه دردت!\r\n"},{"id":216,"category_id":3,"category_code":"s3","source_id":136,"title":"دندان درد","content":"ملا دندانش درد می کرد دستمالی به صورتش بسته بود، یکی از دوستانش او را دید و گفت: بلا دور است ترا چه شده است؟\r\nملا گفت: دندانم درد می کند، دوستش گفت اینکه کاری ندارد زودتر آنرا بکش.\r\nملا گفت: اگر در دهان تو بود می دادم آن را بکشند!\r\n"},{"id":217,"category_id":3,"category_code":"s3","source_id":137,"title":"زن آبستن ","content":"زن ملا آبستن بود ولی نمی زائید، همه نگران شده بودند به همین جهت نزد ملا رفتند تا او چاره اندیشی کند!\r\nملا قدری فکر کرد و سپس چند عدد گردو به آنها داد و گفت: اینکه کاری ندارد، گردو ها به او بدهید تا جلویش بگذارد مطمئن باشید بچه با دیدن آنها زودتر برای خاطر گردو بازی هم که شده بیرون خواهد آمد!\r\n"},{"id":218,"category_id":3,"category_code":"s3","source_id":138,"title":"مرگ ","content":" روزی ملا حسابی مریض شده بود و گمان می کرد که خواهد مرد.\r\nبه همین جهت زنش را صدا زد و گفت: برو بهترین لباست را بپوش و خودت را حسابی آرایش کن!\r\nزن که ناراحت بود به گمان اینکه ملا می خواهد آخرین حرفهایش را به او بزند گریه اش گرفت و گفت: مگر من زن بی وفایی هستم که بخواهم در موقع مردن شوهرم خودم را آرایش کنم؟\r\nملا به او گفت: نه منظورم چیز دیگری است من می خواهم که اگر عزرائیل سراغ من آمد تو را آراسته ببیند و دست از سر من بردارد!\r\n"},{"id":219,"category_id":3,"category_code":"s3","source_id":139,"title":"آرایشگاه ","content":" روزی ملا به دکان آرایشگری رفت آرایشگر ناشی بود و سر او را مدام می برید و جایش پنبه می گذاشت.\r\nملا که از دست او به عذاب آمده بود گفت: بس است دست از سرم بردار، نصف سرم را پنبه کاشتی بقیه را خودم کتان می کارم!\r\n"},{"id":220,"category_id":3,"category_code":"s3","source_id":140,"title":"شیرینی ","content":" روزی ملا از شهری می گذشت، ناگهان چشمش به دکان شیرینی فروشی افتاد به یکباره به سراغ شیرینی ها رفت و شروع به خوردن کرد.\r\nشیرینی فروش شروع کرد به زدن او، ملا همانطوریکه می خورد با صدای بلند می خندید و می گفت: عجب شهر خوبی است و چه مردمان خوبی دارد که با زور و کتک رهگذران را وادار به شیرینی خوردن می کنند!\r\n"},{"id":221,"category_id":3,"category_code":"s3","source_id":141,"title":"مالیات ","content":" زمون قدیم داروغه ها برای جمع آوری خراج و مالیات حاکم الاغ ها را می گرفتند.\r\nیک روز زمان خر بگیری ملانصرالدین با عجله و شتابان وارد خونه ای شد.\r\nصاحبخونه گفت:چی شده؟\r\nملا گفت: بیرون دارن خر میگیرن.\r\nصاحبخونه گفت: خر میگیرن چه ربطی به تو داره؟\r\nملا گفت: مامورین آنچنان عجله داشتن که میترسیدم اشتباها مرا به جای خر بگیرن.\r\n"},{"id":222,"category_id":3,"category_code":"s3","source_id":142,"title":"مسابقه اسب سواری ","content":" ملانصرالدین در عرصه ی مسابقه بر اسبی بنشست و یال اسب در دست گرفت. اسب تاختن آورد و ملا از پشت آن لغزید و از ابتدای یال به انتهای دمب آن رسید !\r\n پس آواز در داد: آهای! آهای …!\r\nاین اسب تمام شد یک اسب دیگر بیاورید!!!\r\n"},{"id":223,"category_id":3,"category_code":"s3","source_id":143,"title":"دستمال ","content":" روزی ملانصرالدین دستمالش را گم کرده بود… نشسته بود و داشت گریه می کرد، دوستانش از او پرسیدند چرا گریه میکنی؟\r\nگفت: دستمالم را گم کرده ام!\r\nگفتند: مگر دستمال گران قیمتی بود؟\r\nگفت: نه ولی زنم گفته بود سیب بخرم و من هم برای این که یادم نرود گوشه ی دستمال را گره زدم، حال اگر از یاد ببرم چه کنم؟\r\n"},{"id":224,"category_id":3,"category_code":"s3","source_id":144,"title":"ملای صرفه جو ","content":" روزی ملانصرالدین مردی را دید که دهانش باز است و دارد خمیازه می کشد. ملانصرالدین نزدیکش شد و در گوشش گفت: حالا که دهانت باز است عیال بنده را هم صدا کن!"},{"id":225,"category_id":3,"category_code":"s3","source_id":145,"title":"ملای زرنگ ","content":" روزی چند تا بچه شیطان در کوچه ای سرگرم بازی بودند که چشمشان به ملانصرالدین افتاد.\r\n بچه ها با هم قرار گذاشتند که به هر دوز و کلکی شده کفشهای ملا را بدزدند. بعد رفتند کنار درخت تنومند و پر شاخ و برگی ایستادند و طوری که ملا بشنود گفتند: همه اهل محل می گویند تا به حال هیچ کس نتوانسته از این درخت بالا برود.\r\n ملا رفت جلو، نگاهی به درخت انداخت و گفت: اینکه کاری ندارد من خیلی راحت می توانم از آن بالا بروم.\r\n بچه ها گفتند: اگر راست می گویی برو بالا ببینیم. ملا کفشهایش را در آورد و گذاشت زیر بغلش و شروع کرد از درخت بالا رفتن. بچه ها گفتند: ملا! چرا کفشهایت را با خودت می بری؟ ملانصرالدین جواب داد: شاید آن بالا جایی بود که لازم شد کفش بپوشم.\r\n"},{"id":226,"category_id":3,"category_code":"s3","source_id":146,"title":"ملای امانت دار ","content":"ملانصرالدین در صحرایی نشسته بود و داشت مرغ بریانی را می خورد.\r\n رهگذری به او رسید و گفت:ملا! اجازه بدهید من هم یک لقمه بردارم. \r\nملانصرالدین جواب داد: خیر اجازه نمی دهم چون مال کسی است.\r\n رهگذر گفت: شما که خودتان مشغول خوردنش هستید. ملا گفت: درست است، ولی صاحب این مرغ آن را به من داده تا من آن را بخورم نه کس دیگری.\r\n"},{"id":227,"category_id":3,"category_code":"s3","source_id":147,"title":"صدقه ","content":" ملانصرالدین گوسفند مردم را می دزدید و گوشتش را صدقه می کرد. از او پرسیدند: این چه کاریست که می کنی؟\r\nملا جواب داد: ثواب صدقه با بره دزدی برابر است فقط در میان پیه و دنبه اش توفیر است!\r\n"},{"id":228,"category_id":3,"category_code":"s3","source_id":148,"title":"اختلاف رنگ ","content":" روزی مردی که موهایی مشکی و ریشی سفید داشت وارد مجلسی شد که اتفاقا” ملانصرالدین در آن حضور داشت. از ملانصرالدین درباره اختلاف رنگ میان ریش و موهای آن مرد سوال کردند. ملا جواب داد: سیاهی موی سر و سفیدی ریش او نشان می دهد که مغزش کمتر از چانه اش کار کرده است."},{"id":229,"category_id":3,"category_code":"s3","source_id":149,"title":"عرق سياه پوست ","content":" ملا غلام سیاهی داشت به نام عماد. روز عید كه لباس نو پوشیده بود, خواست نامه ای به یكی از دوستانش بنویسد. چند قطره از مركب به لباسش چكید. چون به خانه رفت زنش شروع به داد و فریاد كرد كه تو ارزش لباس نو پوشیدن را نداری.\r\n ملا گفت: ای زن خوب بود, اول سبب را میفهمیدی بعد با من نزاع مینمودی.\r\n زن پرسید: سبب سیاه كردن لباس چیست؟\r\n ملا گفت: امروز به ملاحظه عید عماد خواست دست مرا ببوسد. صورتش عرق كرده بود. قطرات عرق او به لباسم چكید سیاه شد.\r\n"},{"id":230,"category_id":3,"category_code":"s3","source_id":150,"title":"درس عبرت ","content":" ملا به حمام رفته بود. خدمتكاران حمام به او اعتنایی نكرده و خدمتی انجام ندادند. ملا وقت رفتن ده دینار اجرت داد و حمامی ها از این بخشش فوق العــــــــاده متحیر مانده ممنون گردیدند. هفته بعد كه باز ملا به حمام رفت احترام بی اندازه ای از هر یك خدمه دید كه هر یك به نوعی اظهار كوچكی مینمودند ولی با این همه ملا وقت بیرون رفتن فقط یك دینار به آنها داد.\r\nحمامی ها بی اندازه متغیر گردیده پرسیدند: سبب بخشش بی جهت هفته قبل و رفتار امروزت چیست؟ \r\nملا گفت: مزد امروز حمام را آنروز و مزد آنروز را امروز پرداختم تا شما با ادب شده مشتری های خود را رعایت بنمائید.\r\n"},{"id":231,"category_id":3,"category_code":"s3","source_id":151,"title":"خر فروشي ملا ","content":"روزی ملا خری را به بازار برد كه بفروشد. هر مشتری كه برایش میرسید, اگر از جلو میامد خر دهانش را باز میكرد كه دندان بگیرد و اگر از عقب میامد لگد میزد\r\nشخصی به ملا گفت: با این وضع كسی خر را نخواهد خرید. ملا گفت: مقصد من هم فروش آن نیست فقط میخواهم مردم بدانند كه من از دست این حیوان چی میكشم؟\r\n"},{"id":232,"category_id":3,"category_code":"s3","source_id":152,"title":"ان شاءا...","content":" روزی همسر ملانصرالدین از او پرسید:\r\nفردا چه می کنی؟\r\nگفت: اگر هوا آفتابی باشد به مزرعه می روم و اگر بارانی باشد به کوهستان می روم و علوفه جمع می کنم.\r\nهمسرش گفت: بگو ان شاءا\r\nاو گفت: ان شاءا... ندارد فردا یا هوا آفتابی است یا بارانی.\r\nاز قضا فردا در میان راه راهزنان رسیدند و او را کتک زدند.\r\nملانصرالدین نه به مزرعه رسید و نه به کوهستان و مجبور شد به خانه بازگردد.\r\nهمسرش گفت: کیست؟\r\nاو جواب داد: ان شاءا... منم.\r\n"},{"id":233,"category_id":3,"category_code":"s3","source_id":153,"title":"خويشاوندي ","content":" یک روز ملانصرالدین خرش را به سختی می زد و رهگذری از آنجا می گذشت و پرسید که چرا می زنی گفت ببخشید اگر می دانستم که با شما خویشاوندی دارد این کارو نمیکردم."},{"id":234,"category_id":3,"category_code":"s3","source_id":154,"title":"الاغ مقصر ","content":" الاغ ملانصرالدین روزی به چراگاه حاکم رفت. حاکم از ملا نزد قاضی شکایت کرد. قاضی ملا را احضار کرد و گفت : ملا ماجرا را توضیح بده. ملا هم گفت : جناب قاضی. فرض کنید شما خر من هستید. من شما را زین می کنم و افسار به شما می بندم و شما حرکت می کنید. بین راه سگها به طرفتان پارس می کنند و شما رَم می کنید و به طرف چراگاه حاکم می روید. حالا انصاف بدید من مقصرم یا شما؟!!"},{"id":235,"category_id":3,"category_code":"s3","source_id":155,"title":"علت نا معلوم ","content":" ملانصرالدین به یکی از دوستانش گفت: خبر داری فلانی مرده؟\r\nدوستش گفت: \"نه! علت مرگش چه بود؟\"\r\nملا گفت: \"علت زنده بودن آن بیچاره معلوم نبود چه رسد به علت مرگش!\"\r\n"},{"id":236,"category_id":3,"category_code":"s3","source_id":156,"title":"ما نوح را فرستاديم ","content":" روزی ملانصرالدین بالای منبر رفت و یک آیه خواند : \" و ما نوح را فرستادیم... \" بعد هرچه کرد ادامه آیه را یادش نیامد تا اینکه یکی از حضار گفت : ملا معطلمون نکن.اگه نوح نمی یاد یکی دیگه رو بفرست!!"},{"id":237,"category_id":3,"category_code":"s3","source_id":157,"title":"مهمان شدن ملانصرالدين","content":"  روزی ملانصرالدین به عده‌ای رسید که مشغول غذا خوردن بودند. رفت جلو و گفت \"السلام یا طایفه‌ی بخیلان.\"\r\nیکی از آن‌ها گفت: \"این چه نسبتی است که به ما می‌دهی؟ خدا گواه است که هیچ‌ یک از ما بخیل نیست.\"\r\nملانصرالدین گفت: \"اگر خداوند این طور گواهی می‌دهد، از حرفی که زدم توبه می‌کنم، و نشست سر سفره‌ی آن‌ها و شروع کرد به غذا خوردن\r\n"},{"id":238,"category_id":3,"category_code":"s3","source_id":158,"title":"کرامت ملا ","content":" روزی ملانصرالدین ادعای کرامت کرد.\r\nگفتند : \"دلیلت چیست؟\"\r\nگفت: \"می‌توانم بگویم الساعه در ضمیر شما چه می‌گذرد؟\"\r\nگفتند: \"اگر راست می‌گویی بگو؟\"\r\nگفت: همه‌ی شما در این فکر هستید که آیا من می‌توانم ادعایم را ثابت کنم یا نه!\r\n"},{"id":239,"category_id":3,"category_code":"s3","source_id":159,"title":"وظيفه و تکليف ","content":" روزی ملانصرالدین بدون دعوت رفت به مجلس جشنی\r\nیکی گفت: \"جناب ملا! شما که دعوت نداشتی چرا آمدی؟\"\r\nملانصرالدین جواب داد: \"اگر صاحب خانه تکلیف خودش را نمی‌داند\r\nمن وظیفه‌ی خودم را می‌دانم و هیچ‌وقت از آن غافل نمی‌شوم\"\r\n"},{"id":240,"category_id":3,"category_code":"s3","source_id":160,"title":"ديرباور","content":"روزی یکی از همسایه‌ها خواست خر ملانصرالدین را امانت بگیرد\r\nبه همین خاطر به در خانه ملا رفت\r\nملانصرالدین گفت: \"خیلی معذرت می‌خواهم خر ما در خانه نیست\"\r\nاز بخت بد همان موقع خر بنا کرد به عرعر کردن\r\nهمسایه گفت: شما که فرمودید خرتان خانه نیست؛\r\nاما صدای عرعرش دارد گوش فلک را کر می‌کند\r\nملا عصبانی شد و گفت: عجب آدم کج خیال و دیرباوری هستی\r\nحرف من ریش سفید را قبول نداری ولی عرعر خر را قبول داری!!\r\n"},{"id":241,"category_id":3,"category_code":"s3","source_id":161,"title":"خون بها","content":"روزی از ملانصرالدین پرسیدند: دوست داری یتیم شوی اما میراث خوار پدرت شوی؟\r\nملا جواب داد: نه. ولی دلم می خواهد او را بکشند تا هم میراث او به من برسد و هم خون بهای او را بگیرم.\r\n"},{"id":242,"category_id":3,"category_code":"s3","source_id":162,"title":"گوش درد ملا","content":"نصرالدین و همسایه‌اش به درد گوش دچار شدند. با هم پیش طبیب رفتند.\r\nطبیب اول گوش همسایه نصرالدین را شست و روغن مالی کرد. همسایه نصرالدین از درد و ناراحتی دادش درآمد. نوبت نصرالدین که شد، عین خیالش نبود.\r\nاز حکیم‌خانه که در آمدند، همسایه نصرالدین گفت:‌ واقعاً که عجب طاقتی داری.\r\nنصرالدین گفت: می‌دانی، ‌چه کار کردم که گوشم درد نگرفت؟\r\nهمسایه پرسید:‌چه کار کردی؟\r\nنصرالدین گفت: هیچی، گوش سالمم را جلو بردم.\r\n"},{"id":243,"category_id":3,"category_code":"s3","source_id":163,"title":"عیال زحمتکش","content":"ملانصرالدین زن خودش را برای رختشویی به خانه دیگران می فرستاد و زن رختشویی هم به خانه آنها می آمد و رخت های آنها را می شست.\r\nاز ملانصرالدین پرسیدند: چرا این کار را می کنی؟\r\nگفت: زنم کار می کند و پول در می آورد و مزد رخت شور را می دهد. این طوری هم احتراممان به جاست و هم در زندگی صرفه جویی می کنیم.\r\n"},{"id":244,"category_id":3,"category_code":"s3","source_id":164,"title":"فضولی ممنوع","content":"شخص فضولی به ملانصرالدین گفت: همسایه ات عروسی دارد.\r\nملا گفت: به من چه!\r\nآن شخص گفت: شاید برای شما شیرینی و شام بیاورند.\r\nملا گفت: به تو چه؟\r\nعیال زحمتکش\r\n"},{"id":245,"category_id":3,"category_code":"s3","source_id":165,"title":"مرگ خر ملا","content":"زن نصرالدین مرد. ولی نصرالدین زیاد ناراحت نشد. اما خرش که مرد تا چند روز آه و ناله می‌کرد. علت را پرسیدند.\r\nگفت: زنم که مرد، همسایه‌ها و دوستان جمع شدند و گفتند غصه نخور، یک زن دیگر برایت پیدا می‌کنیم، ولی خرم که مرد کسی چنین حرفی به من نزد\r\n"},{"id":246,"category_id":3,"category_code":"s3","source_id":166,"title":"ملا و قاضی","content":"یک روز یک نفر سر بگو مگو به ملا نصر الدین سیلی میزنه، ملا هم اونو به دادگاه می کشه و دیّه ی سیلی رو می خواهد.\r\nقاضی از مرد می خواهد که یک سکه به ملا بده. مرد به بهانه ی آوردن سکه از دادگاه فرار میکنه. ملا که متوجه فرار اون میشه، یه سیلی در گوش قاضی می خوابونه و به قاضی میگه: وقتی اومد ، سکّه رو خودت بردار\r\n"},{"id":247,"category_id":3,"category_code":"s3","source_id":167,"title":"ملا را باور کنید!","content":"نصرالدین به خانه یکی از اعیان و اشراف رفت.\r\nنوکر گفت: آقا تشریف ندارند.\r\nاتفاقاً آن شخص کاری با نصرالدین پیدا کرد و روز بعد به خانه نصرالدین رفت و در زد.\r\nنصرالدین از پشت در گفت: من خانه نیستم.\r\nمهمان گفت: چرا شوخی می‌کنی، این که صدای خودت است.\r\nنصرالدین گفت:‌ خودت شوخی می‌کنی، من حرف نوکر تو را دیروز باور کردم، تو امروز نمی‌خواهی حرف خود مرا باور کنی؟\r\n"},{"id":248,"category_id":3,"category_code":"s3","source_id":168,"title":"شمارش ملا","content":"ملانصرالدین ده تا خر داشت. روزی سوار یکی از خرها بود و آنها را شمرد. با خودش گفت:\" چرا نه تا هستند؟\" از خرش پیاده شد و دوباره شمرد. دید ده تا هستند. باز سوار خر خود شد و دید خرها نه تا شدند. این کار را چند بار تکرار کرد و ناچار از خر پیاده شد و گفت:\" این سواری به گم شدن یک خر نمی ارزد!!\""},{"id":249,"category_id":3,"category_code":"s3","source_id":169,"title":"آرزوی ملا","content":"ملا نصرالدین گاوی داشت قوی هیکل، با شاخ هایی تیز و بلند. مدتها بود که ملا آرزو می کرد بنشیند وسط آن شاخ ها و ببیند چه مزه ای دارد.\r\nیک روز که ملا تازه گاوش را از صحرا به خانه آورده بود، گاو رفت گوشه حیاط خوابید و شروع کرد به چرت زدن. ملا فرصت را مناسب دید و تند پرید و نشست روی سر گاو و دو دستی چسبید به آن دو شاخ بلند و تیز.\r\nگاو ترسید، تندی از جا پرید و ملانصرالدین را به هوا پرتاب کرد.\r\nزن ملا، از صدای افتادن یک چیز سنگین، سراسیمه از اتاق بیرون دوید و دید که شوهرش دراز به دراز افتاده وسط حیاط و سر و صورتش غرق خون است. زن، به خیال اینکه ملا مرده، بنا کرد به گریه و زاری و به سر و سینه زدن؛ اما ملا آهسته تکانی به خود داد. به زحمت پا شد نشست و با آه و ناله به زنش گفت:\" آه، گریه نکن عزیز دلم! گر چه خیلی صدمه دیده ام، ولی خوشحالم که به آرزویم رسیدم. خدا را شکر! بالاخره توانستم بنشینم وسط دو شاخ بلند و تیز گاومان! اسفند دود کن، زن!\"\r\n"},{"id":250,"category_id":3,"category_code":"s3","source_id":170,"title":"آتش گرفتن خانه ی ملا","content":" روزی خونه ملا اتیش می گیره بعد ملا داد و هوار راه میندازه و میگه وای بدبخت شدم زنم تو اتیش گیر کرده مردم هم بهش میگن خب برو کمکش کن ملامیگه: اخه من و زنم قرار گذاشتیم که کارهای بیرون خونه را من انجام بدم و کارهای توی خونه را زنم!"},{"id":251,"category_id":3,"category_code":"s3","source_id":171,"title":"قرض دادن ملا","content":"شخصی از ملانصرالدین خواهش کرد که به مدت یک ماه صد دینار به او وام دهد. ملانصرالدین گفت: \"نصف خواهش تو را می توانم بپذیرم.\" آن شخص گمان کرد که ملانصرالدین پنجاه دینار به او خواهد داد. پس گفت: \"مانعی ندارد، پنجاه دینار هم کار مرا راه می اندازد.\" ملانصرالدین گفت: \"اشتباه نکن، تو خواهش کردی صد دینار به تو بدهم که یکماهه آن را بپردازی. من هم نصف خواهشت را قبول می کنم. یعنی پولی ندارم که به تو قرض بدهم ولی یک ماه به تو مهلت می دهم که پول مرا بپردازی!!\""},{"id":252,"category_id":3,"category_code":"s3","source_id":172,"title":"سر شکسته ی ملا","content":"از ملا پرسيدند چرا سرت را بسته اي جواب داد : ديشب با زنم دعوا داشتم آنقدر آب به سرم زد كه سرم را شكست!\r\n گفتند آب سر را نمي شكند جواب داد : آخر آن آب توي كوزه بود\r\n"},{"id":253,"category_id":3,"category_code":"s3","source_id":173,"title":"مرگ زن ملا","content":"روزي به ملا خبر دادند سرت سلامت عيالت فوت شده گفت زن با عقلي بود دست پيش را گرفت !!\r\nچون من خيال داشتم او را طلاق بدهم راضي به زحمت من نشد.\r\n"},{"id":254,"category_id":3,"category_code":"s3","source_id":174,"title":"دزد خانه ی ملا","content":"روزي دزدي به خانه ملا آمد. ملا تا او را ديد داخل گنجه شد و در را بست دزد چون همه خانه را گشت و چيز ناقابلي پيدا نكرد با خود گفت يقينا اشياء قيمتي را در گنجه گذاشته اند پس با زحمت در را کند تا اشياءقيمتي را پیدا كند . چشمش به ملا افتاد كه سر پا ايستاده بود ترس بر او مستولي شد، بالكنت گفت شما اينجا بوديد؟ ملا جواب داد: چون چيز قابلي در خانه نبود از خجالت شما پنهان شدم"},{"id":255,"category_id":3,"category_code":"s3","source_id":175,"title":"لباسهای ملا","content":"از ملا نصرالدین پرسیدند لباست چرک شده چرا نمی شویی؟ گفت دوباره چرک خواهد شد چرا زحمت بیخود بکشم.\r\nگفتند چه اشکال دارد دوباره می شویی. گفت خوب باز هم چرک می شود. گفتند باز هم می شویی.\r\nملا جواب داد من که فقط برای لباس شستن به دنیا نیامده ام کارهای دیگری هم دارم!!\r\n"},{"id":256,"category_id":3,"category_code":"s3","source_id":176,"title":"چاقو و ملا","content":"روزی یه چاقو نشون ملا میدن میگن این چیه ملا نگاه میکنه اول میخنده بعد گریه میکنه بهش میگن چی شده میگه میخندم چون شما نمیدونین این چیه گریه میکنم چون خودمم نمیدونم چیه!"},{"id":257,"category_id":3,"category_code":"s3","source_id":177,"title":"آش گرفتن ملا","content":"روزی در مدخل اصلی شهر شلوغ شده بوده\r\nکسی از ملا سئوال میکند که فلان جا چه خبر است که اینگونه شلوغ شده است؟\r\nملا در پاسخ می گوید اونجا آش می دهند،او هم ظرفی میگیرد وشتابان به آنجا میرود\r\nبعد از چند دقیقه ای ملا میبیند که همه ظرف به دست آنجا می روند\r\nشک می کند!\r\nاز یکی می پرسد انجا چه خبر است؟\r\nبهش می گوید فلان جا آش میدهند.\r\nملا با خود می گوید نکند که راست باشد؟\r\nظرفش را برمی دارد و میرود دنبال آش!!\r\n"},{"id":258,"category_id":3,"category_code":"s3","source_id":178,"title":"بهانه ی ملا","content":"گویند روزی شخصی ارزملا نصرالدین طلب طناب کرد\r\nملا بهش گفت روی طناب ارزن پهن کردم...\r\nشخص باتعجب گفت:ارزن را که روی طناب پهن نمی کنند؟!\r\nملا درپاسخ گفت:مراد بهانه بود که آوردم!!\r\n"},{"id":259,"category_id":3,"category_code":"s3","source_id":179,"title":"مکتب خانه ی ملا","content":"مدتي بود كه ملا به ده بالا ميرفت جهت مكتب داري و درس به بچه هاي ده بالا و مسير بين دو ده را با همان خر معروف ميپيمود ..آخر سال كه رسيد (آخر ترم) ملا از مردم مزد خود را طلب كرد و مردم هم گفتند كه اي ملا تو كه صاحب فضل و كراماتي و از طرفي دانا كه امورات ما ، پس بيا و كاري كه كردي في سبيل الله و قربته االله باشد. \r\nملا گفت كه من صاحب فضلم في سبيل الله كار كنم خرم كه قربته الالله سرش نميشود...\r\n"},{"id":260,"category_id":3,"category_code":"s3","source_id":180,"title":"دعای ملا","content":"ملانصرالدین توی خونه ش نشسته بوده و دائم به خدا می گفته خدایا به من هزار دینار پول بده حتا 999 تا هم قبول نیست. آدم خصیصی که همسایه ملا بوده و از سوراخ سقف ملا را می دیده سریع 999 تا سکه را داخل یک کیسه می ریزه و از سوراخ می ندازه داخل اتاق تا عکس العمل ملا را ببینه. ملانصرالدین سکه ها را می شماره و می بینه 999 تاست. بلند می گه خدایا شکرت همینم قبوله. خصیصه سریع می ره در خونه ملا و بهش می گه سکه ها را بهم پس بده. ملا می گه کدوم سکه ها. خلاصه دعوا بالا می گیره و بالاخره خصیص بهش می گه باید بریم پیش قاضی. ملا یک فکری می کنه و می گه با این لباس های پاره من پیش قاضی نمی یام. اگر می تونی یک لباس به من قرض بده. همسایه خصیص یک لباس گران قیمت براش می یاره و با هم می رن پیش قاضی. اونجا هم خصیص شکایتش را می گه و ملا هم انکار می کنه تا اینکه بالاخره ملا می گه جناب قاضی اگه به حرفش گوش بدید کم کم ادعا می کنه که لباس تنم هم مال اونه. وقتی خصیص می گه معلومه که این لباسا مال منه قاضی دیگه حرفش را باور نمی کنه و به نفع ملانصرالدین رای می ده"},{"id":261,"category_id":3,"category_code":"s3","source_id":181,"title":"دندان درد ملا","content":"دندان ملا درد می کرد نزد دندان ساز رفته گفت دندان مرا بکش.\r\nدندانساز گفت دودینار باید بدهی ملا گفت یکدینار بیشتر نمی دهم.\r\nدندان ساز قبول نکرد ملا ناچار شده و دودینار را داد.\r\nپس دندانی را که درد نمی کرد به او نشان داد چون دندانساز آن را کشید\r\n ملا گفت سهو کردم دندانی که در می کرد دیگریست ،\r\n دندانساز آن را هم کشید آنوقت ملا به او گفت\r\nمی خواستی از من پول زیادی بگیری اما من از تو زرنگ تر بودم\r\n تو را گول زدم و کاری کردم که کشیدن دندان به همان یک دینار تمام شود.\r\nمنبر و ملا\r\nملا در بالاي منبر گفت : هرکس از زن خود ناراضي است بلند شود\r\nهمه ي مردم بلند شدند جز يک نفر\r\nملا به آن مرد گفت : تو از زن خود راضي هستي؟\r\nآن مرد گفت : نه \r\nولي زنم دست و پامو شکسته نمي تونم بلند شم!\r\n"},{"id":262,"category_id":3,"category_code":"s3","source_id":182,"title":"باد شکم ملا","content":"روزی ملا در شهری بر سر سفره حاکم نشسته بود. \r\nحاکم چندین مرتبه در حین غذا عطسه گرفت\r\nوهر دفعه به طرف ملا رو کرده عطسه می کرد ملا گفت: این حرکت شما عیب است. \r\nحاکم جواب داد: در شهر ما این حرکت را عیب نمی دانند! \r\n ملا در حین غذا بادی خارج کرد\r\nحاکم غضبناک شده گفت: چه بی تربیت مردی هستی که در سر سفره غذا \r\n. چنین حرکت بی قاعده ای از تو سر می زند\r\nملاگفت: در شهر ما این حرکت بی قاعده عیب شمرده نمی شود\r\n"},{"id":263,"category_id":3,"category_code":"s3","source_id":183,"title":"شهادت دادن ملا","content":"شخصی به ملا نصرالدین ۲۰ دینار داد تا برای او شهادت دهد\r\nچون پیش قاضی رسیدند آن شخص ادعای خود را بیان کرد\r\nنوبت شهادت ملا نصرالدین رسید گفت:شهادت می دهم که این شخص ۱۰۰\r\nخروار جو از طرفش می خواهد.\r\nقاضی گفت:ادعای او گندم است تو شهادت جو می دهی\r\nگفت:با من قرار گذاشته شهادت بدهم گندم و جو طی نکرده بودیم!!\r\n"},{"id":264,"category_id":3,"category_code":"s3","source_id":184,"title":"ملا و تعمیر خانه","content":"یک روز ملانصرالدین برای تعمیر بام خانه خود مجبور شد،مصالح ساختمانی رابرپشت الاغ خود بگذارد\r\nوبه بالای پشت بام ببرد\r\nالاغ هم بسختی از پله هابالارفت.\r\nملامصالح ساختمانی را از دوش الاغ برداشت وسپس الاغ را بطرف پایین هدایت کرد\r\nملا نمیدانست که خر از پله بالا می رود ولی بهیچ وجه از پله پایین نمی آید.\r\nملا الاغ را رها کرد وبه خانه آمد،که استراحت کند.\r\nدر همین موقع دید الاغ دارد روی پشت بام بالا وپایین می پرد.\r\nوقتی که دوباره به پشت بام رفت،می خواست الاغ را آرام کندکه دید الاغ بهیچ وجه آرام نمی شود به ناچارخودش برگشت پایین\r\nبعدازمدتی متوجه شد که سقف اتاق خراب شده و پاهای الاغ از سقف چوبی آویزان شده،بالاخره الاغ\r\nاز سقف به زمین افتاد ومرد.\r\nبعد ملانصرالدین گفت:که من نمی دانستم که اگر خر به جایگاه رفیع وپست مهمی برسدهم آنجا\r\nراخراب می کند وهم خودش رامی کشد!!\r\n"},{"id":265,"category_id":3,"category_code":"s3","source_id":185,"title":"خواب ملا","content":"شبی ملا در خواب دید که کسی 9 دینار به او می دهد. ملا به او گفت: که الاکرام بالاتمام ، ده دینارش کن . در این اثنا از خواب بیدار شد و چیزی در دست خود ندید. از گفته خود پشیمان شد. فورا\" چشم بر\r\nهم نهاد و دستش را دراز کرد و گفت: همان 9 دینار را بده قبول دارم\r\n"},{"id":266,"category_id":3,"category_code":"s3","source_id":186,"title":"ملا و زنش","content":"روزی ملا سه کیلو گوشت خرید و به خانه برد که زنش غذایی درست کند. زن ملا گوشت را کباب کرد و با\r\nزن همسایه با فراغت خوردند . چون ملا به خانه آمد و غذا خواست زنش گفت: مرا ببخش که غافل شدم\r\nو گربه تمام گوشت ها را خورد. ملا گربه را گرفت و در ترازو گذاشت و دید سه کیلو بیشتر نیست پس\r\nخطاب به زنش گفت: ای بد جنس این وزن سه کیلو گوشت ، پس وزن گربه کجاست؟!\r\n"},{"id":267,"category_id":3,"category_code":"s3","source_id":187,"title":"ملانصرالدین در کوچه","content":"مجلس عروسی یکی از بزرگان بود و ملا نصرالدین را نیز دعوت کرده بودند. \r\nوقتی می خواست وارد شود، در مقابل او دو درب وجود داشت با اعلانی بدین\r\nمضمون: از این درب عروس و داماد وارد می شوند و ازدرب دیگر دعوت شدگان.\r\nملا از درب دعوت شدگان وارد شد.\r\nدر انجا هم دو درب وجود داشت و اعلانی دیگر : از این درب دعوت شدگانی\r\nوارد می شوند که هدیه آورده اند و از درب دیگر دعوت شدگانی که هدیه نیاورده اند\r\nملا طبعا از درب دومی وارد شد.\r\nناگهان خود را در کوچه دید،همان جایی که وارد شده بود!!\r\n"},{"id":268,"category_id":3,"category_code":"s3","source_id":188,"title":"ملا و امیر","content":"روزی ملا بر سر سفره امیر حاضر بود پس از صرف غذا امیر از ملا پرسید:چگونه غذایی بود؟ ملا گفت: بسیار بد.\r\nامیر فرمان داد تا او را بزنند. ملا به فریاد در آمد که برای یک بار بد بود. ولی اگر بار دیگر بخورم بسیار غذای لذیذی\r\nاست. امیر او را بخشید و مقرر کرد تا شام هم به او بدهند!!\r\n"},{"id":269,"category_id":3,"category_code":"s3","source_id":189,"title":"ماه نو","content":"شخصی از ملا سئوال کرد : این ماهی که هر ماه نو می شود، کهنه ی آن را چه می کنند؟ملا در جواب گفت:\r\nای احمق، هنوز این مطلب را نفهمیده ای؟ماه های کهنه را خرد می کنند و با آن این ستاره ها را می سازند که در آسمان است.\r\n"},{"id":270,"category_id":3,"category_code":"s3","source_id":190,"title":"ملا و نابینایان","content":"روزی ملا کنار نهر آبی نشسته بود که ده نفر نابینا به او رسیدند و گفتند: در مقابل دریافت نفری یک دینار ما را از\r\nنهر بگذران. ملا 9 نفر را رد کرد و هنگامی که داشت نفر آخری را از آب می گذراند ناگهان نابینای بیچاره داخل آب\r\nافتاد. با سر و صدای او بقیه متوجه غرق شدن او گردیدند و بانگ بر آوردند که چرا مواظب نبودی و موجب غرق\r\nشدن برادر ما گردیدی؟ ملا در جواب گفت: من یک دینار ضرر کرده ام!!\r\nشما چرا ناراحتید و داد و فریاد راه انداخته اید؟\r\n"},{"id":271,"category_id":3,"category_code":"s3","source_id":191,"title":"ملا و شمع کوچک","content":"در نزدیکی ده ملا مکان مرتفعی بود که شبها باد می آمد و فوق العاده سرد میشد...\r\nدوستان ملا گفتند: ملا اگر بتوانی یک شب تا صبح بدون آنکه از آتشی استفاده کنی در آن تپه بمانی ما یک سور به تو می دهیم و گرنه توباید یک مهمانی مفصل به همه ما بدهی.\r\nملا قبول کرد، شب در آنجا رفت وتا صبح به خود پیچید و سرما را تحمل کرد و صبح که آمد گفت: من برنده شدم و باید به من سور دهید.\r\nگفتند: ملا از هیچ آتشی استفاده نکردی؟ملا گفت: نه، فقط در یکی از دهات اطراف یک پنجره روشن بود و معلوم بود شمعی در آنجا روشن است! \r\nدوستان گفتند: همان آتش تورا گرم کرده و بنابراین شرط را باختی و باید مهمانی بدهی \r\nملا قبول کرد و گفت: فلان روز ناهار به منزل ما بیایید.\r\nدوستان یکی یکی آمدند، اما نشانی از ناهار نبود گفتند: ملا ، انگار نهاری در کار نیست ؟!\r\nملا گفت: چرا ولی هنوز آماده نشده! \r\nدو سه ساعت دیگه هم گذشت باز ناهار حاضر نبود.\r\nملا گفت: آب هنوز جوش نیامده که برنج را درونش بریزم.\r\nدوستان به آشپزخانه رفتند ببیننند چگونه آب به جوش نمی آید؟! دیدند ملا یک دیگ بزرگ به طاق آویزان کرده دو متر پایین تر یک شمع کوچک زیر دیگ نهاده\r\nگفتند : ملا این شمع کوچک نمی تواند از فاصله دو متری دیگ به این بزرگی را گرم کند ؟!\r\nملا گقت : چطور از فاصله چند کیلومتری می توانست مرا روی تپه گرم کند؟ شما بنشینید تا آب جوش بیاید و غذا آماده شود.\r\n"},{"id":272,"category_id":3,"category_code":"s3","source_id":192,"title":"لباس راه راه","content":"یک روز ملانصرالدین خرش را در جنگل گم می کند. موقع گشتن به دنبال آن یک گورخر پیدا می کند. به آن می گوید: ای کلک لباس راه راه پوشیدی تا نشناسمت؟!"},{"id":273,"category_id":3,"category_code":"s3","source_id":193,"title":"خر نامرد","content":"روزی ملانصرالدین از راهی می گذشت. درختی پیدا کرد و زیر سایه آن کمی خوابید.\r\nناغافل دزدی آمد و خرش را دزدید. ملا وقتی از خواب بیدار شد و دید خرش نیست، خورجینش را برداشت و به راه خودش ادامه داد تا اینکه چشمش به خر دیگری افتاد که بدون صاحب بود.\r\nآن را گرفت و کوله بارش را روی آن گذاشت و به راه خود ادامه داد و با خودش گفت: خدا گر ز حکمت ببندد دری، ز رحمت گشاید در دیگری.\r\nچند روز بعد صاحب خر پیدا شد و گفت: این خر مال من است.\r\nملانصرالدین هم زیر بار نمی رفت و می گفت مال من است.\r\nصاحب خر پرسید: خر تو نر بود یا ماده؟ ملا گفت: نر\r\nصاحب خر گفت: این خر ماده است. ملانصرالدین هم جواب داد: اما خر من، خر نامردی بود.\r\n"},{"id":274,"category_id":3,"category_code":"s3","source_id":194,"title":"تختخواب چهار نفره","content":"عیال ملا مرد و او رفت و زن بیوه ای گرفت. زن مرتب از شوهر سابقش حرف می زد و ملا هم از زن سابقش.\r\nشبی ملا زنش را از روی تخت به پایین انداخت. زن با چشم و چالی کبود شده پیش پدرش رفت و از ملا شکایت کرد.\r\nپدر زن ملا، او را صدا کرد و از او خواست درباره کارش توضیح بدهد\r\nملا گفت: من بی تقصیرم، تخت ما دو نفره است اما ما چهار نفر هستیم یعنی من و زن سابقم، دختر شما و شوهر سابقش. حالا هم چون روی تخت جا نبود عیال از روی تخت پایین افتاد.\r\n"},{"id":275,"category_id":3,"category_code":"s3","source_id":195,"title":"گردنبند","content":"ملانصرالدین دو تا زن داشت و همیشه از دست درخواست های آنها در عذاب بود. یک روز برای هر دوی آنها دستبندی خرید تا از غرغر کردن های آنها خلاص شود.\r\nچند روزی گذشت و هر دو زن پیش ملا آمدند و از او پرسیدند که کدام یک از ما را بیشتر دوست داری؟\r\nملانصرالدین جواب داد: به آن که دستبند داده ام علاقه بیشتری دارم.\r\n"},{"id":276,"category_id":3,"category_code":"s3","source_id":196,"title":"ملای بی فکر","content":"شخصی با زن ملا سر و سری داشت. یک روز آن شخص جوانی را پیش زن ملا فرستاد.\r\nزن ملا از او خوشش آمد و آن را به خانه دعوت کرد. یک دفعه آن مرد وارد خانه شد. زن ملا جوان را در جایی پنهان کرد و با مرد شروع کرد به خوش و بش کردن.\r\nدر همین موقع صدای پای ملا شنیده شد. زن ملا که اوضاع را اینطور دید چاقویی به دست رفیقش داد و گفت: با من دعوا کن و بگو غلام مرا کجا پنهان کرده ای\r\nملا وارد اتاق شد و پرسید: چه اتفاقی افتاده است؟\r\nزن گفت: غلام این مرد فرار کرده و به خانه ما پناه آورده و من او را قایم کرده ام که او را نزند. آن مرد با شفاعت ملا جوان را بخشید و هر دو از آنجا بیرون آمدند.\r\n"},{"id":277,"category_id":3,"category_code":"s3","source_id":197,"title":"نامرد چهارمی","content":"ملانصرالدین زنی گرفته بود که قبلا\" دو بار ازدواج کرده بود و هر دو شوهرش هم مرده بودند.\r\nملانصرالدین در حال احتضار بود، زن بالای سر او گریه می کرد و می گفت: ملا جان! به کجا می روی و من را تنها به دست کی می سپاری؟ ملا در همان حال جواب داد: به نامرد چهارمی.\r\n"},{"id":278,"category_id":3,"category_code":"s3","source_id":198,"title":"مجازات ملانصرالدین","content":"روزی ملانصرالدین خطایی مرتکب می شود و او را نزد پادشاه می برند تا مجازاتش را تعیین کند. پادشاه برایش حکم مرگ صادر می کند، اما مقداری رافت به خرج می دهد و به وی می گوید اگر بتوانی ظرف سه سال به خرت سواد خواندن و نوشتن بیاموزانی از مجازاتت درمی گذرم.\r\nملانصرالدین هم قبول می کند و ماموران حاکم رهایش می کنند. عده ای به ملا می گویند مرد حسابی! آخر تو چگونه می توانی به یک الاغ خواندن و نوشتن یاد بدهی؟ ملانصرالدین می فرماید: انشاءالله در این سه سال یا شاه می میرد یا خرم!\r\n"},{"id":279,"category_id":3,"category_code":"s3","source_id":199,"title":"آنجا که خدا هست ","content":"یکی از دوستان ملا نصر الدین به کنایه از او پرسید\r\n\" اگر بگویی خدا کجاست، یک سکه به تو می دهم\"\r\nملا نصرالدین پاسخ داد:\" اگر بگویی خدا کجا نیست، دو سکه به تو می دهم\"\r\n"},{"id":280,"category_id":3,"category_code":"s3","source_id":200,"title":"خواستگاری کردن از دختر ملا","content":"روزی ملا گاوی لاغر داشت که می خواست آن را به بازار شهر ببرد و بفروشد.\r\nملا به زنش گفت: \r\n- این گاو لاغر به درد ما نمی خورد.\r\nزن ملا چیزی نگفت و فقط به شوهرش و آن گاو نگاه کرد. ملانصرالدین ادامه داد:\r\n- گاو را به بازار می برم تا به کسی بفروشم و از شرش خلاص شوم.\r\nگاو همان طور که سرش پایین بود و دم تکان می داد، همراه ملا از حیاط بیرون رفت.\r\nزن ملا به طرف در حیاط دوید و فریاد کشید:\r\n- آهای ! با تو هستم! مگر صدایم را نمی شنوی؟\r\n ملا برگشت و با چهره ای درهم کشیده گفت:\r\n- چه خبره ؟! چرا فریاد می کشی؟\r\nهمسرش با همان صدای بلند گفت:\r\n- بهتر است زود به خانه برگردی؛ چون قرار است برای دخترمان خواستگار بیاید.\r\nملانصرالدین که با شنیدن این خبر خوشحال شده بود، با مهربانی گفت:\r\n- بسیار خوب؛ خیلی زود برمی گردم.\r\nبعد هم به راه افتاد و زیرلب با خوش گفت:\r\n- سال ها از وقت شوهر کردن دختره گذشته است. خدا کند خواستگار این دفعه ، او را بپسندد...\r\nبازار شهر شلوغ بود و مردم همه چیز خرید و فرش می کردند؛ اما هیچ کس سراغ گاو ملا نمی آمد؛ چون خیلی لاغر و بی حال به نظر می رسید.\r\nکم کم غروب می شد و ملانصرالدین که چند ساعتی برای فروش گاو فریاد بی نتیجه کشیده بود، خودش هم مثل گاو، خسته و بی حال در گوشه ای نشست.\r\nمرد دلالی که زمان زیادی ملا را زیر نظر داشت و منتظر همین لحظه بود، جلو آمد و گفت:\r\n- اگر من بتوانم این گاو مردنی را بفروشم، چه قدر به من می دهی؟\r\nملانصرالدین که باور نداشت کسی آن گاو را بخرد، بدون معطلی گفت:\r\n- هر چه فروختی، نصف نصف شریک هستیم.\r\nمرد دلال پذیرفت و چند قدم دورتر از ملا و گاوش ایستاد و فریاد کشید:\r\n- آی مردم! بیایید که یک معامله سودمند در انتظارتان است.....\r\nچند نفری که نزدیک او بودند ، دورش حلقه زدند. مرد دلال در حالی که با انگشت به گاو اشاره می کرد، گفت:\r\n- یک گاو فروشی داریم که خیلی کم خوراک است. اما روزی ده من شیر میدهد و تازه، شش ماهه هم آبستن است. هر کس این گاو را بخرد، به زودی صاحب گوساله ای خواهد شد.\r\nعاقبت ، یک نفر آدم زودباور که حرف دلال را درست می دانست، حاضر شد تا پول خوبی برای گاو بدهد.\r\nملانصرالدین با رضایت و خوش حالی فراوان از انجام آن معامله، به قولش عمل کرد و نصف پول را به مرد دلال داد. بعد هم با عجله به سوی خانه راه افتاد و زیرلب گفت:\r\n- باید زودتر به خانه بروم تا از زبان تند و تلخ همسرم در امان باشم.\r\nوقتی به خانه رسید، متوجه شد که خواستگاران ، قبل از او به خانه اش آمده اند. همسرش در حالی که تندتند از دخترشان تعریف می کرد ، به ملانصرالدین چشم غره رفت که چرا دیر آمدی؟\r\nملانصرالدین که هنوز هم از خوشحالی گاو بیرون نیامده بود، خواست زنش را راضی کند؛ برای همین بود که بدون مقدمه وارد گفت و گو شد:\r\n- زنم درست می گوید و این دختر ما خیلی خوب و مفید است......\r\nجوان خواستگار به خواهر و مادرش نگاه کرد. انگار که هیچ کدام آنان از حرف ملا سر در نیاوره بودند. زن ملا هم چشم درانیده بود و ملا را نگاه می کرد.\r\nملا که به یاد بازار گرمی مرد دلال افتاده بود، خواست حرف های او را تقلید کند و در ادامه حرف خودش گفت:\r\n- از همه ی حرف ها من و همسرم که بگذریم، باید بگویم که دختر ما شش ماهه آبستن است و تا چند ماه دیگر صاحب یک بچه خواهد شد و....\r\nهمسر ملا هر چه را دم دستش بود، به سمت ملا پرتاب کرد و خواستگاران پا به فرار گذاشتند.\r\n"},{"id":281,"category_id":3,"category_code":"s3","source_id":201,"title":"تعارف بی موقع ملا","content":"روزی در مزرعه ای نشسته بود سواری عبور می کرد گفت بفرمائید سوار از اسب پیاده شد پرسید افسار اسب را کجا بکوبم؟ ملا که گمامن نداشت تعارفش چنین نتیجه ای بدهد گفت: بر سر زبان من !"},{"id":282,"category_id":3,"category_code":"s3","source_id":202,"title":"کفاره گناه ","content":"ملا را زنی بدشکلی نصیب شده بود شبی بی جهت مدتی از چهره او تفرس کرد زن پرسید سبب اینکه این همه مرا نگاه می کنی چیست گفت امروزچشمانم به صورت زن خوبروئی افتاد وهرچه خواستم از صورتش چشم بردارم میسر نشد امشب بکفاره آن برای اینکه گناهم بخشیده شود دو برابر آنچه به او نگاه کردم چشمم را به صورت تو می اندازم!!!"},{"id":283,"category_id":3,"category_code":"s3","source_id":203,"title":"سبب گریه ملا ","content":"روزی ملا در عقب جنازه یکی به آواز بلند گریه می کرد یکی از مهمانان او را تسلیت داد پرسید مرحوم با شما چه نسبتی داشتند ملا گفت نسبتی نداشتند و سبب گریه من هم همین است که هیچ نسبتی با ندارم!!!"},{"id":284,"category_id":3,"category_code":"s3","source_id":204,"title":"میخ کوبیدن ملا","content":"روزی میخی بر دیوار طویله می کوفت اتفاقا دیوار طویله سوراخ شد وطویله خانه همسایه که در جنب آن بود نمودار شد و اسب وشتر بسیاری در آنجا دید به زن مژده داد گفت بیا طویله ای پر از اسب و شتر پیدا کردم گمانم این است که اینها را کسی از قدیم الایام در اینجا پنهان کرده است واز عهد دقیانوس در اینجا مانده است ."},{"id":285,"category_id":3,"category_code":"s3","source_id":205,"title":"ملا و مرد ثروتمند","content":"ملا نصر الدین به خانه مرد ثروتمندی رفت تا برای فقرا صدقه ای از او بگیرد \r\nکلفت پیری در را باز کرد\r\nملا گفت:\" بگو ملا نصر الدین آمده تا برای فقرا صدقه جمع کند.\"\r\nکلفت به داخل خانه رفت و چند دقیقه بعد برگشت.\r\n\". اربابم در خانه نیست\"\r\n پس با این که به فقرا کمک نمی کند، توصیه ای برایش دارم: به او بگو دفعه بعدکه در خانه نیست، سرش را پشت پنجره جا نگذارد. آدم فکر می کند دارد دروغ می گوید!\r\n"},{"id":286,"category_id":3,"category_code":"s3","source_id":206,"title":"زن کامل","content":"ملا نصر الدین با دوستی صحبت می کرد.\r\n\" خوب! ملا هیچ وقت به فکر ازدواج افتاده ای؟\"\r\nملا نصر الدین پاسخ داد: فکر کرده ام. جوان که بودم تصمیم گرفتم زن کاملی پیدا کنم. از صحرا گذشتم و به دمشق رفتم و با زن پر حرارت و زیبایی آشنا شدم، اما او از دنیا بی خبر بود.\r\nبعد به اصفهان رفتم، آنجا هم با زنی آشنا شدم که معلومات زیادی درباره آسمان و زمین داشت اما زیبا نبود.\r\nبه قاهره رفتم و نزدیک بود با دختر زیبا، با ایمان و تحصیل کرده ای ازدواج کنم.\r\n\" پس چرا با او ازدواج نکردی؟\"\r\n!! آه رفیق! متاسفانه او هم دنبال مرد کاملی می گشت\r\n"},{"id":287,"category_id":3,"category_code":"s3","source_id":207,"title":"مرتاض و ملا","content":"ملا نصرالدین از جلو غاری می گذشت، مرتاضی را در حال مراقبه دید و از او پرسید دنبال چه می گردد؟\r\nمرتاض گفت:\" بر حیوانات مطالعه می کنم، از آن ها درس های زیادی می گیرم که می تواند زندگی آدم را زیر و رو کند.\" \r\nملا نصرالدین پاسخ داد:\" بله، قبل از این، یک ماهی جان مرا نجات داده. اگر هرچه را که می دانی به من بگویی، من هم ماجرای ماهی را برایت می گویم.\"\r\nمرتاض از جا پرید:\" این اتفاق فقط می توانست برای یک قدیس رخ بدهد.\"\r\nبنابراین هرچه را که می دانست به او گفت.\r\n-\" حالا که همه چیز را به تو گفتم، خوشحال می شوم که بدانم چگونه یک ماهی جان شما را نجات داد؟!\"\r\nملا نصرالدین پاسخ داد:\" خیلی ساده! موقع قحطی داشتم از گرسنگی می مردم و به لطف آن ماهی توانستم سه روز دیگر دوام بیاورم.\"\r\n"},{"id":288,"category_id":3,"category_code":"s3","source_id":208,"title":"مرشد شدن ملا","content":"مریدی از ملا نصرالدین پرسید:\r\n\" چطور مرشد عرفان شدید؟\"\r\nملا نصرالدین گفت:\" همه ما می دانیم در زندگی چه باید بکنیم، اما هیچ وقت این موضوع را نمی پذیریم.\r\nبرای درک این واقعیت مجبور شدم وضعیت عجیبی را از سر بگذرانم.\r\nیک روز کنار خیابان نشسته بودم و فکر می کردم چه کنم. مردی از راه رسید و جلو من ایستاد.\r\nخواستم از جلو من کنار برود و دستم را تکان دادم. او هم همین کار را کرد.\r\nفکر کردم چه بامزه! حرکت دیگری کردم و او هم از من تقلید کرد.\r\nشروع کردیم به آواز خواندن و هر ورزشی که بگویی انجام دادیم.\r\nمدام احساس می کردم حالم بهتر است و از رفیق جدیدم خوشم آمده بود.\r\nچند هفته گذشت و از او پرسیدم:\" استاد بگو چه کار باید بکنم؟\"\r\nپاسخ داد:\" اما من فکر می کردم تو مرشدی!\"\r\n"},{"id":289,"category_id":3,"category_code":"s3","source_id":209,"title":"ملا و مریدانش","content":"یکی از شاگردان ملا نصرالدین پرسید:\" تمام استادان می گویند که گنج روح، چیزی است که باید در تنهایی کشف شود. پس برای چه ما با همیم؟\"\r\nملا نصرالدین پاسخ داد:\" با همید، چون جنگل همیشه نیرومندتر از درختی تنهاست!\r\nجنگل رطوبت هوا را تامین می کند، در مقابل طوفان مقاوم تر است و به باروری خاک کمک می کند.\"\r\n- اما چیزی که یک درخت را مقاوم می کند، ریشه است. و ریشه یک درخت نمی تواند به ریشه درخت دیگری کمک کند. \r\n. جنگل همین است\r\nهر درخت با درخت دیگر متفاوت است، هر درخت ریشه مستقل دارد. راه آنانی که می خواهند به خدا برسند، همین است:\r\nاتحاد برای یک هدف، و هم زمان آزاد گذاشتن هر یک از اعضای گروه تا به شیوه خودش تکامل یابد\r\n"},{"id":290,"category_id":3,"category_code":"s3","source_id":210,"title":"ملا و عدالت آسمانی","content":"می گن زمانای قدیم یه روز 3 تا پسر بچه میرن پیش ملا نصرالدین\r\nمیگن ما 10 تا گردو داریم میشه اینا رو با عدالت بین ما تقسیم کنی ؟\r\nملا می گه با عدالت آسمونی یا عدالت زمینی ؟\r\nبچه ها میگن خوب عدالت آسمونی بهتره با عدالت آسمونی تقسیم کن.\r\nملا 8 تا گردو می ده به اولی 2 تا می ده به دومی دو تا پس گردنی محکم هم می زنه به سومی\r\nبچه ها شاکی میشن می گن این چه عدالتیه ملا ؟\r\nملا می گه خدا هم نعمتاشو بین بنده هاش همینجوری تقسیم کرده\r\n"},{"id":291,"category_id":3,"category_code":"s3","source_id":211,"title":"داستان ملا و مادرش ","content":"ملا شنید که مادر زنش را آب برده است بر عکس جهت رودخانه ای که او در آنجا غرق شده بود شروع به راه رفتن نمود!\r\nبا تعجب از او پرسیدند چرا خلاف جهت آب به دنبال مادر زنت می گردی؟\r\nملا گفت : چونکه همه کارهای او برعکس بود احتمال می دهم که جنازه اش را هم آب برعکس برده باشد.\r\n"},{"id":292,"category_id":3,"category_code":"s3","source_id":212,"title":"داستان ملا و گربه ","content":"زن ملا مشغول پر کندن چند مرغ بود. گربه ای آمد و یکی از مرغ ها را قاپید و فرار کرد... \r\nزن فریاد زد: ملا، گربه مرغ را برد. ملا از توی یکی از اتاق ها با صدای بلندگفت: قرآن را بیاور! گربه تا این را شنید مرغ را انداخت و فرار کرد.\r\nگربه های دیگر دورش جمع شدند و با افسوس پرسیدند: تو که این همه راه ٬مرغ را آوردی چرا آنرا انداختی؟ گربه گفت: مگر نشنیدید گفت قرآن را بیاور؟\r\nگربه ها گفتند قرآن کتاب آسمانی آنهاست به ما گربه ها چه ربطی دارد؟گربه گفت: اشتباه شما همین جاست! ملا می خواست آیه ای پیدا کند و بگوید از این به بعد گوشت گربه حلال است و نسل مان را از روی زمین بردارد!\r\n"},{"id":293,"category_id":3,"category_code":"s3","source_id":213,"title":"گردو شکستن ملا","content":"ملا روزی گردو می شکست٬ گردویی از زیر سنگش جسته ناپدید شد٬ گفت سبحان الله همه چیز از مرگ می گریزد حتی بهائم."},{"id":294,"category_id":3,"category_code":"s3","source_id":214,"title":"چادر شب فروختن ملا","content":"روزی ملا چادرشبی  پاره به بازار جهت فروختن برد کسی نخرید. گفتند: این چادر شب پاره است و به چیزی نمی ارزد. گفت :دروغ می گویید به جهت آنکه اگر پاره بود مادرم در آن آرد نمی ریخت."},{"id":295,"category_id":3,"category_code":"s3","source_id":215,"title":"شتر سواری ملا","content":"روزی ملا بر شتر سوار بود و به جایی میرفت. شتر از طریق مقصود بیرون رفت و راه دیگری در پیش گرفت یکی از رفقای قدیمی به او رسید و پرسید به کجا میروی؟ گفت: هر کجا که میل شتر باشد."},{"id":296,"category_id":3,"category_code":"s3","source_id":216,"title":"شرط طلاق","content":"ملا در بازار پیراهن زری برای زنش میخرید. رفیقش گفت: تو میخواستی زنت را طلاق بدهی پس پیراهن زری برای کی میخری؟ ملا جواب داد: زنم شرط کرده که اگر پیراهن زری برایش بخرم پیش قاضی بیاید و طلاق را قبول کند."},{"id":297,"category_id":3,"category_code":"s3","source_id":217,"title":"برای تجربه","content":"زن ملا به او گفت: سبب این که در خواب اینقدر خروپف میکنی چیست؟ ملا گفت: چرا دروغ میگوئی مخصوصا دفعه پیش که به من گفتی دو شب تا صبح خواب را برخودم حرام کرده که ببینم راستی خروپف میکنم یا نه. ابدا صدائی نشنیدم و یقین دارم که تو اشتباه کرده ای و خودت خروپف میکنی خیال کرده ای که من هستم."},{"id":298,"category_id":3,"category_code":"s3","source_id":218,"title":"استراحت ملا","content":"شخصی از ملا پرسید: ساعات استراحت تو چه وقت است؟ ملا گفت: چند ساعت در شب و دو ساعت در بعد ازظهرها که او میخوابد. آن شخص پرسید: او کیست؟ ملا گفت: عیال من. شخص مزبور گفت: نادان پرسیدم خودت کی استراحت میکنی. به عیالت چه کار داشتم. ملا جواب داد: نادان خودت هستی مگر نمیدانی؟ ساعاتی که زنم در خواب است من میتوانم نفس راحتی بکشم."},{"id":299,"category_id":3,"category_code":"s3","source_id":219,"title":"تعارف راستی","content":"در موقع بی پولی رفقای ملا از او مهمانی خواستند. ملا هر چه عذر کرد نپذیرفتند. بالاخره به اصرار، خود آنها روزی را معین کردند و ملا هم قبول کرد به شرط آنکه غذایی حاضری بسازند. روز موعود برای چاشت نان و ماست و خرما و پنیر و انگور تهیه دیده بود و به دوستانش اصرار بی اندازه میکرد که خجالت نکشید این غذا متعلق به خود تان است، همانطور که در منزل میل میکنید اینجا هم بی تکلیف صرف نمائید. رفقا از تعارف ملا خیلی شاد گشتند و با کمال میل چاشت را صرف کرده و روزی را به خوشی گذرانیدند. ولی وقت بیرون آمدن از منزل ملا، کفش و عبای خود را نیافتند. از ملا پرسیدند: آنها را کجا گذاشته اید؟ ملا گفت: نزد سمسار سرگذر. دوستان سوال کردند: برای چه؟ ملا جواب داد: مگر نه اینکه وقتی غذا میخوردید میگفتم مال خود تان است، دروغ نگفتم قیمت کفش و عبایتان بود. رفقا مجبور شدند پولی بین خود جمع کرده به ملا بدهند که برود کفش و عبایشان را از گرو بیرون آورد. ملا هم به آنها فهماند که اصرار بی موقع ضررش نصیب خود شخص خواهد گردید."},{"id":300,"category_id":3,"category_code":"s3","source_id":220,"title":"خاراندن سر","content":"ملا با شخصی سر به یک بالین گذاشته بود. سر ملا میخارید. شروع کرد به خاریدن سر رفیقش. او از خواب جسته گفت: چرا سر مرا میخارانی؟ ملا جواب داد: خیال کردم سر خودم است. اگرچه دیدم خوشم نمیاید."},{"id":301,"category_id":3,"category_code":"s3","source_id":221,"title":"تلافی لت خوردن","content":"دختر ملا گریه کنان نزد او آمده گفت: شوهرم مرا مفصل لت کرد. ملا هم چوبی برداشته او را چوبکاری کرد و گفت: برو به شوهرت بگو اگر دختر مرا لت و کوب کردی من به تلافی آن زنت را خوب  لت کردم."},{"id":302,"category_id":3,"category_code":"s3","source_id":222,"title":"سن ملا و برادرش","content":"از ملا پرسیدند تو و برادرت از نظر سن با یکدیگر چقدر فرق دارید؟ ملا فکری کرده و گفت: سال قبل مادرم میگفت برادرم یکسال از من بزگتر است بنابراین امسال حتما هر دو هم سال شده ایم."},{"id":303,"category_id":3,"category_code":"s3","source_id":223,"title":"پیدا کردن انگشتر","content":"ملا انگشتر خویش را در اطاق گم کرده بود. مدتی جستجو کرد ولی چون آنرا نیافت از اطاق بیرون رفته و در حیاط خانه شروع به جستجو کرد. زنش که او را دیده بود، پرسید: ملا تو که انگشتر را در اطاق گم کرده ای برای چه حیاط را جستجو میکنی؟ ملا دستی به ریش خود کشیده و گفت: اطاق تاریک است و چشمم به خوبی نمیتواند ببیند، به همین دلیل در حیاط که روشن تر است به دنبال انگشترم میگردم."},{"id":304,"category_id":3,"category_code":"s3","source_id":224,"title":"زرنگی ملا","content":"ملا نزد حاکم رفته گفت: حُکمی بنویس که من از هر کسی که از زن خود بترسد یک مرغ بگیرم. حاکم که به شوخی ملا عادت داشت دستور داد حکم را نوشته به دست ملا دادند. ملا چند روزی سفر کرده و قریب صد مرغ همراه آورد. او در بدو ورود٬ واردقصرحاکم شد. حاکم که او را با آنهمه مرغ دید تعجب کرده پرسید. ملا این همه مرغ را به وسیله آن حکم به دست آورده ای؟ ملا گفت: حوصله ام سر رفت ورنه به عدد تمام مردان قلمرو حکومت شما مرغ تهیه میکردم. حالا خدمت شما رسیدم که عرض کنم در فلان شهر کنیز بسیار زیبایی دارای آواز خوب که برای همخوابی حاکم خیلی مناسب بود دیدم. حاکم دست به بینی خود گذاشته گُفت: ملا مراقب باش خانم از پشت درب گوش میدهد. ملا گفت: چون کار دارم خواهش دارم دستور بدهید یکی مرغ به مرغهای من اضافه کنند تا مرخص شوم. حاکم فهمید ملا خواسته خود او را امتحان کند. به او آفرین گفته امر کرد یک خروس به او بدهند. ملا هم خوشحال شده راه بازار را پیش گرفته مرغها را فروخته وبه  خانه رفت."},{"id":305,"category_id":3,"category_code":"s3","source_id":225,"title":"ملا و سکه ی نقره","content":"ملا نصر الدین هر روز در بازار گدایی می کرد، و مردم با نیرنگی، او را دست می انداختند.\r\nدو سکه به او نشان می دادند که یکی شان از طلا بود و دیگری از نقره\r\nاما ملا نصرالدین همیشه سکه نقره را انتخاب می کرد.\r\nاین داستان در تمام منطقه پخش شد.\r\nهر روز گروهی زن و مرد می آمدند و دو سکه به او نشان می دادند و ملا نصر الدین همیشه سکه نقره را انتخاب می کرد.\r\nتا اینکه مرد مهربانی از راه رسید و از این که ملا نصر الدین را آن طور دست می انداختند، ناراحت شد.\r\nدر گوشه میدان به سراغش رفت و گفت:\" هر وقت دو سکه به تو نشان دادند، سکه طلا را بردار. این طوری هم پول بیشتری گیرت می آید و هم دیگر دستت نمی اندازند.\"\r\nملا نصر الدین پاسخ داد:\" ظاهرا حق با شماست. اما اگر سکه طلا را بردارم دیگر مردم به من پول نمی دهند تا ثابت کنند من از آنها احمق ترم. شما نمی دانید تا حالا با این کلک چه قدر پول گیر آورده ام!!\"\r\n\" اگر کاری که می کنی هوشمندانه باشد، هیچ اشکالی ندارد که تو را احمق بدانند...\"\r\n"},{"id":306,"category_id":3,"category_code":"s3","source_id":226,"title":"ارباب و نوکر","content":"از ملا پرسیدند ارباب مهمتر است یا زارع؟ملا فکری کرد و دستی به ریش خود کشید و گفت: زارع. گفتند: برای این حرف خود دلیلی هم داری؟ گفت: بلی... چون اگر زارع نباشد تا کار کند ارباب از گرسنگی خواهد مرد."},{"id":307,"category_id":3,"category_code":"s3","source_id":227,"title":"ماه بهتر است","content":"روزی شخصی از ملا پرسید: ماه بهتر است یا خورشید!؟\r\nملا گفت ای نادان این چه سوالی است که از من می پرسی؟ خوب معلوم است٬ خورشید روزها بیرون می آید که هوا روشن است و نیازی به وجودش نیست!\r\nولی ماه شبهای تاریک را ورشن می کند٬به همین جهت نفعش خیلی بیشتر از ضررش است.\r\n"},{"id":308,"category_id":3,"category_code":"s3","source_id":228,"title":"دوست ملا","content":"روزی ملا با دوستش خورش بادمجان می خورد. ملا از او پرسید خورش بادمجان چه جور غذایی است؟\r\nدوست ملا گفت : غذای خیلی خوبی است و راجع به منافع آن سخن گفت.\r\nبعد از اینکه غذایشان را خوردند و سیر شدند بادمجان دلشان را زد به همین جهت ملا شروع کرد به بدگویی از بادمجان و از دوستش پرسید: خورش بادمجان چگونه غذایی است!؟\r\nدوست ملا گفت: من دوست توام نه دوست بادمجان به همین جهت هر آنچه را که تو دوست داری برایت می گویم.\r\n"},{"id":309,"category_id":3,"category_code":"s3","source_id":229,"title":"گم شدن ملا","content":"روزی ملا خرش را گم کرده بود٬ راه می رفت و شکر می کرد. دوستش پرسید حالا خرت را گم کرده ای دیگر چرا خدا را شکر می کنی؟\r\nملا گفت به خاطر اینکه خودم بر روی آن ننشسته بودم و الا خودم هم با آن گم شده بودم!؟\r\n"},{"id":310,"category_id":3,"category_code":"s3","source_id":230,"title":"داماد شدن ملا","content":"روزی از ملا پرسیدند : شما چند سالگی داماد شدید؟\r\nملا گفت به خدا یادم نیست چونکه آن زمان هنوز به سن عقل نرسیده بودم.\r\n"},{"id":311,"category_id":3,"category_code":"s3","source_id":231,"title":"خانه ملا","content":"روزی جنازه ای را می بردند پسر ملا از پدرش پرسید : پدرجان این جنازه را کجا می برند؟\r\nملا گفت او را به جایی می برند که نه آب هست نه نان ونه پوشیدنی هست و نه چیز دیگری\r\nپسر ملا گفت : فهمیدم او را به خانه ما می برند.\r\n"},{"id":312,"category_id":3,"category_code":"s3","source_id":232,"title":"ملا و گوسفند","content":"روزی ملا از بازار یک گوسفند خرید در راه دزدی طناب گوسفند را از گردن آن باز کرد و گوسفند را به دوستش داد و طناب را به گردن خود بست و چهار دست و پا به دنبال ملا را افتاد.\r\nملا به خانه رسید ناگهان دید که گوسفندش تبدیل به جوانی شده است.\r\nدزد رو به ملا کرد و گفت من مادرم را اذیت کرده بودم او هم مرا نفرین کرد من گوسفند شدم ولی چون صاحبم مرد خوبی بود دوباره به حالت اول بازگشتم.\r\nملا دلش به حال او سوخت و گفت: اشکالی ندارد برو ولی یادت باشد که دیگر مادرت را اذیت نکنی!\r\nروز بعد که ملا برای خرید به بازار رفته بود گوسفندش را آنجا دید. گوش او را گرفت و گفت ای پسر احمق چرا مادرت را ناراحت کردی تا دوباره نفرینت کند و گوسفند شوی!؟\r\n"},{"id":313,"category_id":3,"category_code":"s3","source_id":233,"title":"لباس نو","content":"روزی ملا  به مجلس میهمانی رفته بود اما لباسش مناسب نبود به همین جهت هیچکس به او احترام نگذاشت و به او تعارف نکرد!\r\nملا به خانه رفت و لباسهای نواش را پوشید و به میهمانی برگشت٬ اینبار همه او را احترام گذاشتند و با عزت و احترام او را بالای مجلس نشاندند! ملا هنگام صرف غذا در حالیکه به لباسهای نواش تعرف می کرد گفت: بفرمایید این غذاها مال شماست اگر شما نبودید اینها مرا داخل آدم حساب نمی کردند.\r\n"},{"id":314,"category_id":3,"category_code":"s3","source_id":234,"title":"نردبان فروشی ملا","content":"روزی ملا در باغی بر روی نردبانی رفته بود و داشت میوه می خورد صاحب باغ او را دید و با عصبانیت پرسید: ای مرد بالای نردبان چکار می کنی؟ملا گفت نردبان می فروشم!\r\nباغبان گفت : در باغ من نردبان می فروشی؟\r\nملا گفت: نردبان مال خودم هست هر جا که دلم بخواهد آنرا می فروشم!\r\n"},{"id":315,"category_id":3,"category_code":"s3","source_id":235,"title":"ملا در جنگ","content":"روزی ملا به جنگ رفته بود و با خود سپر بزرگی برده بود. ولی ناگهان یکی از دشمنان سنگی بر سر او زد و سرش را شکست.\r\nملا سپر بزرگش را نشان داد و گفت: ای نادان سپر به این بزرگی را نمی بینی و سنگ بر سر من می زنی؟\r\n"},{"id":316,"category_id":3,"category_code":"s3","source_id":236,"title":"بچه ملا","content":"روی ملا خواست بچه اش را ساکت کند به همین جهت او را بغل کرد و برایش لالایی می گفت و ادا در می آورد٬ که ناگهان بچه روی او ادرار کرد!\r\nملا هم ناراحت شد و بچه را خیس کرد.\r\nزنش گفت: ملا این چه کاری بود که کردی؟\r\nملا گفت: باید برود و خدا را شکر کند اگر بچه من نبود و غریبه بود او را داخل حوض می انداختم.\r\n"},{"id":317,"category_id":3,"category_code":"s3","source_id":237,"title":"خانه عزاداران","content":"روزی ملا در خانه ای رفت و از صاحبخانه قدری نان خواست٬ دخترکی در خانه بود و گفت : نداریم!\r\nملا گفت: لیوانی آب بده! \r\nدخترک پاسخ داد: نداریم! \r\nملا پرسید: مادرت کجاست؟\r\nدخترک پاسخ داد : عزاداری رفته است!\r\nملا گفت: خانه شما با این حال و روزی که دارد باید همه قوم و خویشان به تعزیت به اینجا بیایند نه اینکه شما جایی به عزاداری بروید.\r\n"},{"id":318,"category_id":3,"category_code":"s3","source_id":238,"title":"قبر دراز","content":"روزی ملا از گورستان عبور می کرد قبر درازی را دید٬ از شخصی پرسید اینجا چه کسی دفن است!\r\nشخص پاسخ داد : این قبر علمدار امیر لشکر است!\r\nملا با تعجب گفت: مگر او را با علمش دفن کرده اند؟\r\n"},{"id":319,"category_id":3,"category_code":"s3","source_id":239,"title":"قیمت حاکم","content":"روزی ملا به حمام رفته بود اتفاقا حاکم شهر هم برای استحمام آمد حاکم برای اینکه با ملا شوخی کرده باشد رو به او کرد و گفت : ملا قیمت من چقدر است؟\r\nملا گفت : بیست تومان.\r\nحاکم ناراحت شد و گفت : مردک نادان اینکه تنها قیمت لنگ حمام من است.\r\nملا هم گفت: منظورم همین بود و الا خودت ارزش نداری!\r\n"},{"id":320,"category_id":3,"category_code":"s3","source_id":240,"title":"درخت گردو","content":"روزی ملا زیر درخت گردو خوابیده بود که ناگهان گردویی به شدت به سرش اصابت کرد و سرش باد کرد. بعد از آن شروع کرد به شکر کردن\r\nمردی از آنجا می گذشت وقتی ماجرا را شنید گفت:اینکه دیگر شکر کردن ندارد.\r\nملا گفت: احمق جان  اگر به جای درخت گردو زیر درخت خربزه خوابیده بودم نمیدانم عاقبتم چه بود.\r\n"},{"id":321,"category_id":3,"category_code":"s3","source_id":241,"title":"پرواز در آسمانها","content":"مردی که خیال می کرد دانشمند است و در نجوم تبهری دارد یک روز رو به ملا کرد و گفت:\r\nخجالت نمی کشی خود را مسخره مردم نموده ای و همه تو را دست می اندازند در صورتیکه من دانشمند هستم و هر شب در آفاق و انفس سیر می کنم.\r\nملا گفت : ایا در این سفرها چیز نرمی به صورتت نخورده است؟\r\nدانشمند گفت : اتقاقا چرا؟\r\nملا با تمسخر پاسخ داد: درست است همان چیز نرم دم الاغ من بوده است.\r\n"},{"id":322,"category_id":3,"category_code":"s3","source_id":242,"title":"مرکز زمین","content":"یک روز شخصی که می خواست سر بسر ملا بگذارد او را مخاطب قرار داد و از او پرسید: جناب ملا مرکز زمین کجاست؟\r\nملا گفت : درست همین جا که ایستاده ای.\r\nاتفاقا از نظر علمی هم به علت اینکه زمین کروی شکل است پاسخ وی درست می باشد.\r\n"},{"id":323,"category_id":3,"category_code":"s3","source_id":243,"title":"الاغ دم بریده","content":"یک روز ملا الاغش را به بازار برد تا بفروشد٬ اما سر راه الاغ داخل لجن رفت و دمش کثیف شد٬ ملابا خودش گفت: این الاغ را با آن دم کثیف نخواهند خرید به همین جهت دم را برید.\r\nاتفاقا در بازار برای الاغش مشتری پیدا شد اما تا دید الاغ دم ندارد از معامله پشیمان شد\r\nاما ملا بلافاصله گفت : ناراحت نشوید دم الاغ در خورجین است!؟\r\n"},{"id":324,"category_id":3,"category_code":"s3","source_id":244,"title":"خروس شدن ملا","content":"یک روز ملا به گرمابه رفته بود تعدادی جوان که در آنجا بودند تصمیم گرفتند سر بسر او بگذارند به همین جهت هر کدام تخم مرغی آورده بودند و رو به ملا کردند و گفتند: ما هر کدام قدقد می کنیم و یک تخم می گذاریم اگر کسی نتوانست باید مخارج حمام دیگران را بپردازد! \r\nملا ناگهان شروع کرد به قوقولی قوقو! جوانان با تعجب از او پرسیدند ملا این چه صدایی است بنا بود مرغ شوی!\r\nملا گفت : این همه مرغ یک خروس هم لازم دارند.\r\n"},{"id":325,"category_id":3,"category_code":"s3","source_id":245,"title":"دم خروس","content":"یک روز شخصی خروس ملا را دزدید و در کیسه اش گذاشت٬\r\nملا که دزد را دیده بود او را تعقیب نمود و به او گفت:خروسم را بده! دزد گفت : من خروس تورا ندیده ام.\r\nملا دفعتا دم خروس را دید که از کیسه بیرون زده بود به همین جهت به دزد گفت درست است که تو راست می گویی ولی این دم خروس که از کیسه بیرون آمده است چیز دیگری می گوید.\r\n"}];
